    pub severity: CodecSeverity,
    pub message: String,
    pub primary_span: Option<SourceSpan>,
    pub related_spans: Vec<SourceSpan>,
}

/// ⚠️ A failed codec operation. Failures remain structured so hosts never need to parse text.
