    const INTO: Dialect = TXT_DIALECT;
    const FIDELITY: IoFidelity = IoFidelity::Exact;
    async fn serialize(from: &Block2dSnapshot) -> IoResult<IoPayload> {
        serialize_dsl_txt(from)
    }
}

