            },
        );
        registry.insert(
            space::S_SPACE_SCHEMA.to_string(),
            ArtifactKindEntry {
                descriptor: OsArtifactDescriptor {
                    kind: space::S_SPACE_SCHEMA.into(),
                    label: LocalizedLabel::native("Space", "Space"),
                    source_format: space::S_SPACE_SCHEMA.into(),
                    component_kind: "space".into(),
