                direction,
                media_type: semio_framework::MediaType { class: semio_framework::MediaClass::TwoD, form: semio_framework::MediaForm::Vector },
                kind_id: Some("2d.drawing".into()),
                required: false,
                multiplicity: semio_framework::PortMultiplicity::One,
            },
        };
        WorkflowNode {
            id: id.into(),
            plugin_id: "draw".into(),
            app_id: "draw".into(),
            label: id.into(),
