fn every_word(bits:u64)->Iso16757Snapshot{use crate::part_2::GeometryNode;let mut s=fixture();let word=f64::from_bits(bits);for v in &mut s.catalogue.product_series{for v in v.shared_property_values.values_mut(){replace_value_words(v,word);}}for v in &mut s.catalogue.products{for d in &mut v.parameter_domains{for v in &mut d.allowed_values{replace_value_words(v,word);}if let Some(v)=&mut d.default_value{replace_value_words(v,word);}}for v in &mut v.variants{for v in v.parameter_values.values_mut(){replace_value_words(v,word);}for p in &mut v.property_values{replace_value_words(&mut p.value,word);}}for p in &mut v.static_properties{replace_value_words(&mut p.value,word);}}for v in &mut s.catalogue.property_definitions{if let Some(u)=&mut v.unit{u.si_factor=word;}}for v in &mut s.dictionary.properties{if let Some(u)=&mut v.unit{u.si_factor=word;}for c in &mut v.value_constraints{if c.min.is_some(){c.min=Some(word);}if c.max.is_some(){c.max=Some(word);}}}for v in s.geometry.objects.values_mut(){let mut stack:Vec<_>=v.shape.iter_mut().chain(v.symbolic.iter_mut()).collect();while let Some(n)=stack.pop(){match n{GeometryNode::Primitive{parameters,..}=>for v in parameters.values_mut(){*v=word;},GeometryNode::Transform{translation,rotation_deg,child}=>{*translation=[word;3];*rotation_deg=[word;3];stack.push(child);},GeometryNode::Boolean{children,..}=>stack.extend(children),_=>{}}}for v in &mut v.spaces{v.bounds.min=[word;3];v.bounds.max=[word;3];}for v in &mut v.surfaces{v.bounds.min=[word;3];v.bounds.max=[word;3];}for v in &mut v.ports{v.position=[word;3];v.direction=[word;3];}}for v in &mut s.selection.constraints{replace_value_words(&mut v.value,word);}for v in s.part_number_inputs.values_mut(){replace_value_words(v,word);}let mut stack:Vec<_>=s.catalogue.extensions.fields.values_mut().collect();while let Some(v)=stack.pop(){match v{dsl::DslValue::Number(dsl::Number::Float(v))=>*v=word,dsl::DslValue::Array(items)=>stack.extend(items),dsl::DslValue::Object(items)=>stack.extend(items.iter_mut().map(|(_,v)|v)),_=>{}}}s}
#[test]fn sqlite_snapshot_all_ieee_fields_have_independent_exact_word_oracle(){use std::io::Write;use std::process::{Command,Stdio};use store::sqlite_snapshot::*;let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true}),expected=BigInt.asIntN(64,BigInt('0x'+process.env.SEMIO_TEST_WORD));let count=0;for(const t of d.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all())for(const c of d.query('PRAGMA table_info('+t.name+')').all())if(c.name.endsWith('_ieee754_bits'))for(const v of d.query('SELECT '+c.name+' AS value FROM '+t.name).all())if(v.value!==null){if(v.value!==expected)throw Error('independent bit identity');count++;}if(count<40)throw Error('full scalar coverage');await Bun.write(Bun.stdout,d.serialize());d.close();";for word in f["binary64Words"].as_array().unwrap(){let word=word.as_str().unwrap();let s=every_word(u64::from_str_radix(word,16).unwrap());let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_TEST_WORD",word).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let restored=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),d);restored.retire_sqlite_snapshot();s.retire_sqlite_snapshot();}}
