            let rx = read_channel_number(input, "rx")?;
            let ry = read_channel_number(input, "ry")?;
            let handle = k.ellipse(cx, cy, rx, ry).map_err(|error| map_kernel_error(&error))?;
            Ok(channel_output("draw.drawing", drawing_dict(k, &handle)?))
        })
    }
