        };
        let fixture: SequenceHostSnapshot = semio_framework_pack_json::from_json_str(literal, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| IoError::from_value_error(error.under("MdIntoSequence")))?;
