                    serializer_entry::<Fem2dSnapshot, export::stl::v_ascii::any::Fem2dIntoStl>(FEM2D_DIALECT),
                    serializer_entry::<Fem2dSnapshot, export::obj::v3_0::any::Fem2dIntoObj>(FEM2D_DIALECT),
                ]
