#[test]fn sqlite_snapshot_en1993_all_ninety_six_fields_have_independent_exact_word_oracle(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()),{safeIntegers:true});const expected=BigInt.asIntN(64,BigInt('0x'+process.env.SEMIO_TEST_WORD));let count=0;for(const t of d.query(\"SELECT name FROM sqlite_schema WHERE type='table'\").all()){for(const c of d.query('PRAGMA table_info('+t.name+')').all()){if(!c.name.endsWith('_ieee754_bits'))continue;for(const v of d.query('SELECT '+c.name+' AS value FROM '+t.name).all()){if(v.value!==expected)throw Error('independent bit identity');count++;}}}if(count!==96)throw Error('all96scalars');await Bun.write(Bun.stdout,d.serialize());d.close();";for word in f["binary64Words"].as_array().unwrap(){let word=word.as_str().unwrap();let s=every_word(u64::from_str_radix(word,16).unwrap());let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let mut child=Command::new("bun").args(["-e",script]).env("SEMIO_TEST_WORD",word).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let restored=restore(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&restored),d);}}
