        let mut wrapper = CommonAttrs::default().with_transform(vec![TransformOp::Matrix { a,b,c,d,e,f }]).with_opacity(node.opacity.to_string());
        wrapper.extra_attrs.push(attr("data-layer-id", &node.id));
