}

/// 🧪️ The only operation this probe document supports: whole-value replace — mirrors
/// `crate::os_store::impl_whole_record_config!`'s "no field-level diff" shape, the simplest legal
/// `Mutation` implementor.
#[derive(Clone, Debug, PartialEq, serde::Serialize, serde::Deserialize)]
pub enum ProbeMutation {
    SetValue(serde_json::Value),
}

/// 🧷️ Hand-built `store::Mutation::DESCRIPTORS` entry for `ProbeMutation`'s one operation — not
/// `#[derive(dsl::Mutations)]` (see `ProbeMutation`'s own docstring): that derive requires each
/// variant to wrap a real `MutationLeaf` payload, and `SetValue`'s foreign `serde_json::Value`
/// field is not one. Field values satisfy `store::validate_mutation_leaf_descriptor`'s contract by
/// hand.
const PROBE_SET_VALUE_DESCRIPTOR: store::MutationLeafDescriptor = store::MutationLeafDescriptor {
    schema_version: 1,
    owner: "os/mcp/workspace/🧬️mutations/set-value",
    semantic_kind: "set-value",
    display_name: "Set Value",
    emoji: "🧪",
    aggregate_variant: "SetValue",
    payload_schema: PROBE_SCHEMA,
    text_opcode: None,
    binary_tag: None,
    invertibility: store::MutationInvertibility::ExplicitMutation,
    diff_participation: store::MutationDiffParticipation::Detect,
    outcome_classes: &[store::MutationOutcomeClass::Applied],
    composition: store::MutationComposition::Atomic,
    required_language_surfaces: &[store::MutationLanguageSurface::Rust],
};

impl store::Mutation<ProbeSnapshot> for ProbeMutation {
    type Diff = ProbeDiff;
    const DESCRIPTORS: &'static [store::MutationLeafDescriptor] = &[PROBE_SET_VALUE_DESCRIPTOR];

    fn descriptor(&self) -> &'static store::MutationLeafDescriptor {
        &Self::DESCRIPTORS[0]
    }

    fn diff(&self, _base: &ProbeSnapshot) -> store::MutationOutcome<ProbeDiff> {
        let ProbeMutation::SetValue(value) = self;
        store::MutationOutcome::new(ProbeDiff(value.clone()))
    }

    fn inverse(&self, base: &ProbeSnapshot) -> Result<Vec<Self>, semio_framework_value::ValueError> {
    Ok((|| {
        vec![ProbeMutation::SetValue(base.0.clone())]

    })())
}
}

/// 🌉️ Hand-written — `ProbeMutation::SetValue` wraps a foreign `serde_json::Value` field, same gap
/// as [`ProbeSnapshot`]'s impl above (the derive cannot map a foreign type's shape into `DslValue`),
/// and the same no-`to_dsl_value` recursion rule. Externally tagged as `{"SetValue": <payload>}` —
/// byte-identical to what `#[derive(ToValue)]` and `serde`'s default emit for a tagless
/// single-unnamed-field variant, which is what `🧫️fixtures/🔣️first-party-codecs.json`'s `probeCodec`
/// section pins.
impl store::ToValue for ProbeMutation {
    fn to_value(&self) -> store::DslValue {
        let ProbeMutation::SetValue(value) = self;
        store::DslValue::object([(PROBE_SET_VALUE_DESCRIPTOR.aggregate_variant.to_string(), store::DslValue::from(value))])
    }
}
impl store::FromValue for ProbeMutation {
    fn from_value(value: store::DslValue) -> Result<Self, store::ValueError> {
        let store::DslValue::Object(entries) = value else {
            return Err(store::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("expected a one-key `{}` object, found {value:?}", PROBE_SET_VALUE_DESCRIPTOR.aggregate_variant)));
        };
        match <[(String, store::DslValue); 1]>::try_from(entries) {
            Ok([(key, payload)]) if key == PROBE_SET_VALUE_DESCRIPTOR.aggregate_variant => Ok(ProbeMutation::SetValue(serde_json::Value::from(payload))),
            Ok([(key, _)]) => Err(store::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("unknown variant `{key}`, expected `{}`", PROBE_SET_VALUE_DESCRIPTOR.aggregate_variant))),
            Err(entries) => Err(store::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, format!("expected exactly one variant key, found {}", entries.len()))),
        }
    }
}

impl store::OpText for ProbeMutation {
    fn print_op(&self) -> String {
        let ProbeMutation::SetValue(value) = self;
        serde_json::to_string(value).unwrap_or_else(|_| "null".to_string())
    }

    fn parse_op(line: &str) -> Result<Self, semio_framework_diagnostic::TextError> {
        serde_json::from_str(line).map(ProbeMutation::SetValue).map_err(|error| semio_framework_diagnostic::TextError::new(semio_framework_value::ValueRefusalKind::InvalidValue, error.to_string(), semio_framework_diagnostic::TextSpan::at(0, 0)))
    }
}

impl store::OpBinary for ProbeMutation {
    fn encode_op(&self) -> Result<Vec<u8>, store::ProtocolError> {
        let ProbeMutation::SetValue(value) = self;
        serde_json::to_vec(value).map_err(|error| store::ProtocolError::Malformed { what: "probe-op", offset: 0, detail: error.to_string() })
    }

    fn decode_op(bytes: &[u8]) -> Result<Self, store::ProtocolError> {
        serde_json::from_slice(bytes).map(ProbeMutation::SetValue).map_err(|error| store::ProtocolError::Malformed { what: "probe-op", offset: 0, detail: error.to_string() })
    }
}

