use super::*;
use crate::os_dsl::schema::{FieldSpec, FieldValue, RecordLayout, RecordSpec, RecordValue, Shape};
use crate::sqlite_snapshot::{SqliteDatabase, SqliteDatabaseLimits, SqliteRow, SqliteSnapshotControl, SqliteSnapshotPhase, SqliteValue};
use semio_framework_value::{ValueError, ValueRefusalKind};

struct DecodedBuffers {
    buffers: Vec<Vec<u8>>,
}
std::thread_local! { static COMPLETED_DECODERS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) }; }
std::thread_local! { static ORDINARY_DECODER_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) }; static CONTROLLED_DECODER_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) }; }

fn buffer_spec() -> RecordSpec {
    RecordSpec::new(Some("buffers"), RecordLayout::Lines, vec![FieldSpec::new(1, "buffers", Shape::List(Box::new(Shape::Bytes64)))])
}
fn buffer_spec_controlled<C: crate::os_dsl::NativeSchemaControl>(control: &mut C) -> Result<RecordSpec, semio_framework_value::ValueError> {
    control.scoped_stage(|control| {
        control.begin_stage(1)?;
        let mut fields = control.allocate_vec(1)?;
        let shape = Shape::List(crate::os_dsl::schema::producer::boxed(Shape::Bytes64, control)?);
        fields.push(crate::os_dsl::schema::producer::field(1, "buffers", shape, control)?);
        control.step()?;
        crate::os_dsl::schema::producer::record(Some("buffers"), RecordLayout::Lines, fields, control)
    })
}
fn buffer_spec_producer() -> crate::os_dsl::RecordSpecProducer {
    crate::os_dsl::RecordSpecProducer { ordinary: buffer_spec, decoding: |control| buffer_spec_controlled(control), encoding: |control| buffer_spec_controlled(control) }
}
