pub(super) fn reconstruct_grip_location(reader:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgBlockGripLocationComponent,ValueError>{let row=reader.component("dwg_block_grip_location_component",id)?;Ok(DwgBlockGripLocationComponent{evaluation_expression:reconstruct_expression(reader,id)?,grip_type:unsigned(row,1)?,grip_expression:row.text(2)?.into()})}
pub(super) fn project_proxy(projection:&mut Projection<'_,'_>,id:i64,value:&DwgDynamicBlockProxyNode)->Result<(),ValueError>{project_expression(projection,id,&value.evaluation_expression)?;projection.insert_key("dwg_dynamic_block_proxy_node",id,&[])}
pub(super) fn reconstruct_proxy(reader:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgDynamicBlockProxyNode,ValueError>{reader.component("dwg_dynamic_block_proxy_node",id)?;Ok(DwgDynamicBlockProxyNode{evaluation_expression:reconstruct_expression(reader,id)?})}

