pub(super) fn reconstruct_dictionary_variable(reader:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgDictionaryVariable,ValueError>{Ok(DwgDictionaryVariable{value:reader.component("dwg_dictionary_variable",id)?.text(1)?.into()})}
pub(super) fn project_annotation_scale(projection:&mut Projection<'_,'_>,id:i64,value:&DwgAnnotationScale)->Result<(),ValueError>{projection.insert_key("dwg_annotation_scale",id,&[T(&value.name),R(value.paper_units),R(value.drawing_units),I(i64::from(value.is_unit_scale))])}
