pub(super) fn project_sort_entities_table(projection:&mut Projection<'_,'_>,id:i64,value:&DwgSortEntitiesTable)->Result<(),ValueError>{
 projection.insert_key("dwg_sort_entities_table",id,&[I(high(value.block_header_handle)),I(low(value.block_header_handle))])?;
