    let mut work = 0;
    for row in source {
        tick(control, &mut work)?;
        if row.rowid <= 0 || row.values.len() != width || row.integer(0)? != row.rowid {
            return Err(invalid("OPC identity or physical row width differs"));
        }
        rows.push(row);
    }
    sort(&mut rows, control, |a, b| Ok(a.rowid.cmp(&b.rowid)))?;
