        put(
            record,
            1,
            match value {
                GltfJson::Bool(value) => emit(value, control)?,
                _ => absent(control)?,
            },
            control,
        )?;
        put(
            record,
            2,
            match value {
                GltfJson::Number(value) => emit(value, control)?,
                _ => absent(control)?,
            },
            control,
        )?;
        put(
            record,
            3,
            match value {
                GltfJson::String(value) => FieldValue::Text(control.copy_text(value)?),
                _ => absent(control)?,
            },
            control,
        )?;
