    impl QualifiedBoundedFirstStepProof {
        fn key(&self) -> semio_framework::ToolFactoryKey {
            semio_framework::ToolFactoryKey::new(self.row.controller_id, self.row.tool_id)
        }

        fn schema_id(&self) -> String {
