    impl<A: ArtifactApp> MountedTypedCommandFullOperation<A> {
        /// 🧮️ Records what the store answered for ONE publication unit. The checkpoint carries the
        /// store's own cursor, completed items and completed bytes; a unit that repeats the
        /// previous checkpoint verbatim moved nothing and raises no progress, so an owner that can
        /// never advance still runs its streak up to
        /// [`TYPED_OPERATION_STALL_FAULT_CEILING`], while a ladder folding one mutation per unit
        /// resets that streak every unit however many mutations the edit carries.
        fn note_publication_checkpoint(&mut self, checkpoint: store::ArtifactStoreOneItemCheckpoint) {
            if self.publication_checkpoint != Some(checkpoint) {
                self.publication_checkpoint = Some(checkpoint);
                self.publication_progress = self.publication_progress.saturating_add(1);
            }
        }

        /// 🚫️ A rejected worker admission never ran the job, so no completion value will ever
        /// arrive: publication would spin on `completion.take() == None` for as long as the host
        /// keeps advancing it. The operation is terminal the moment its session is refused —
        /// cancel the lease so the next publication unit mints the exact fault page.
        fn drive_worker_step(&mut self, pool: &semio_framework_async::WorkerPool, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Worker {
                return Ok(PluginCloseStep::Blocked { reason: "typed command awaits its bounded revision-validated publication or ACK turn" });
            }
            if let Some(rejected) = self.session_rejected.as_mut() {
                let step = rejected.close_step(1, maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                if rejected.terminal_is_empty() {
                    self.session_rejected = None;
                    self.stage = MountedTypedCommandFullOperationStage::Publishing;
                    self.terminal_fault.get_or_insert_with(|| {
                        ArtifactBoundedToolFault::from_fault(&Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.admission-capacity"), "typed operation worker session admission was refused by the process-wide session capacity"))
                    });
                    if let Some(lease) = self.cancellation_lease.as_ref() {
                        lease.cancel();
                    }
                }
                return Ok(match step {
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::InteractiveJobCloseStep::Blocked => PluginCloseStep::AwaitingInput { reason: "typed operation rejected-session close awaits its worker handback" },
                    semio_framework_job::InteractiveJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                });
            }
            if let Some(outcome) = self.terminal_outcome.as_mut() {
                let step = outcome.close_step(1, maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                if !outcome.terminal_is_empty() {
                    return Ok(match step {
                        semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                        semio_framework_job::JobPayloadCloseStep::Complete => PluginCloseStep::Blocked { reason: "typed command retained outcome reported false terminal" },
                    });
                }
                self.terminal_outcome = None;
                let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-session"), "typed operation lost its persistent mounted session during outcome handback"))?;
                if self.terminal_seen {
                    session.begin_close();
                } else if session.resume().is_err() {
                    return Ok(PluginCloseStep::AwaitingInput { reason: "typed operation outcome handback awaits its worker session" });
                }
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.typed-operation-session"), "typed operation lost its persistent worker session before publication"))?;
            if self.terminal_seen {
                let step = session.close_step(1, maximum_bytes.min(semio_framework_job::JOB_PAYLOAD_PAGE_BYTES));
                if session.terminal_is_empty() {
                    self.session = None;
                    self.stage = MountedTypedCommandFullOperationStage::Publishing;
                }
                return Ok(match step {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    semio_framework_job::WorkerJobCloseStep::Blocked => PluginCloseStep::AwaitingInput { reason: "typed operation mounted session close awaits its worker handback" },
                    semio_framework_job::WorkerJobCloseStep::Complete => PluginCloseStep::Pending { released_items: 1, released_bytes: 0 },
                });
            }
            match session.pump_one_for_interactive_turn(pool, semio_framework_async::Lane::Interactive) {
                Ok(semio_framework_job::WorkerJobPoll::Outcome | semio_framework_job::WorkerJobPoll::Terminal) => {
                    let terminal = session.checked_out_outcome().is_some_and(semio_framework_job::StepOutcome::is_terminal);
                    let Some(outcome) = session.take_checked_out_outcome() else {
                        return Ok(PluginCloseStep::Blocked { reason: "typed operation checked-out outcome changed during one mounted turn" });
                    };
                    if let semio_framework_job::StepOutcome::Fault(fault) = &outcome {
                        self.terminal_fault = Some(ArtifactBoundedToolFault::from_retained_fault(&fault.detail));
                    }
                    if matches!(outcome, semio_framework_job::StepOutcome::Cancelled | semio_framework_job::StepOutcome::Fault(_)) {
                        if let Some(lease) = self.cancellation_lease.as_ref() {
                            lease.cancel();
                        }
                    }
                    if let semio_framework_job::StepOutcome::CheckpointReady(checkpoint) = &outcome {
                        let next = self.progress.unwrap_or(0).max(checkpoint.applied_progress);
                        self.progress_pending |= self.progress != Some(next);
                        self.progress = Some(next);
                    }
                    if terminal && self.progress.is_some() {
                        self.progress_pending = true;
                    }
                    self.terminal_seen = terminal;
                    self.terminal_outcome = Some(outcome);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Ok(semio_framework_job::WorkerJobPoll::Submitted | semio_framework_job::WorkerJobPoll::Rejected) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                Ok(_) => Ok(PluginCloseStep::AwaitingInput { reason: "typed operation mounted worker awaits its next outcome" }),
                Err(semio_framework_job::MountedWorkerJobPumpFault::Submit(semio_framework_job::WorkerJobSubmitFault::Contention(_)))
                | Err(semio_framework_job::MountedWorkerJobPumpFault::Submit(semio_framework_job::WorkerJobSubmitFault::Pool(semio_framework_async::WorkerSubmitErrorKind::Contended | semio_framework_async::WorkerSubmitErrorKind::Saturated)))
                | Err(semio_framework_job::MountedWorkerJobPumpFault::Take(semio_framework_job::WorkerJobTakeFault::Pending)) => Ok(PluginCloseStep::AwaitingInput { reason: "typed operation mounted worker awaits transient scheduler authority" }),
                Err(_) => Ok(PluginCloseStep::Blocked { reason: "typed operation mounted worker failed to make structural progress" }),
            }
        }

        fn next_token(&self) -> TypedOperationResultToken {
            TypedOperationResultToken { receiver: self.meta.instance_id, operation: self.operation.operation.0, generation: self.operation.generation.0, sequence: self.result_sequence, attempt: 1 }
        }

        fn queue_page(&mut self, page: TypedOperationResultPage) -> Result<(), Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Publishing || self.result_page.is_some() {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.result-page-state"), "typed operation can retain exactly one unacknowledged result page"));
            }
            self.result_page = Some(page);
            self.result_page_presented = false;
            self.stage = MountedTypedCommandFullOperationStage::AwaitingAck;
            Ok(())
        }

        fn reject_cancelled_publication(&mut self) -> Result<bool, Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Publishing {
                return Ok(false);
            }
            let lease = self.cancellation_lease.as_ref().ok_or_else(|| plugin_sdk_fault("typed-operation publication lacks its exact cancellation lease"))?;
            if !lease.handle.publication_scope.is_cancelled() && !lease.document_claim.as_ref().is_some_and(|claim| claim.is_cancelled()) && !lease.publication_claim.is_cancelled() && !lease.token.is_cancelled_now() {
                return Ok(false);
            }
            if self.publication.is_none() {
                if let Some(completion) = self.completion.as_ref() {
                    self.publication = completion.take()?;
                }
            }
            if let Some(pending) = self.pending_artifact_publication.as_mut() {
                pending.begin_close();
            }
            if let Some(pending) = self.pending_child_publication.as_mut() {
                pending.begin_close();
            }
            self.ui_pending = false;
            let page = match self.terminal_fault.as_ref() {
                Some(fault) => {
                    let mut framed = [0; TYPED_OPERATION_FAULT_PAGE_BYTES];
                    let len = fault.framed_page_bytes(&mut framed);
                    TypedOperationResultPage::try_new(self.next_token(), TypedOperationResultLane::Fault, &framed[..len])?
                }
                None => {
                    let lane = operation_progress::cancellation_result_lane(self.user_cancel_requested, false);
                    let detail: &[u8] = if lane == TypedOperationResultLane::Terminal { b"" } else { b"typed-operation cancelled before its next publication unit" };
                    TypedOperationResultPage::try_new(self.next_token(), lane, detail)?
                }
            };
            self.queue_page(page)?;
            Ok(true)
        }

        fn take_result_page(&mut self) -> Option<TypedOperationResultPage> {
            if self.result_page_presented {
                return None;
            }
            self.result_page_presented = true;
            self.result_page.clone()
        }

        fn acknowledge_result_page(&mut self, token: TypedOperationResultToken) -> Result<bool, Fault> {
            let Some(page) = self.result_page.as_ref() else { return Ok(false) };
            if page.token != token || self.stage != MountedTypedCommandFullOperationStage::AwaitingAck {
                return Ok(false);
            }
            let lane = page.lane;
            if matches!(
                lane,
                TypedOperationResultLane::Artifact
                    | TypedOperationResultLane::Config
                    | TypedOperationResultLane::Draft
                    | TypedOperationResultLane::Presence
                    | TypedOperationResultLane::Transient
                    | TypedOperationResultLane::WindowConfig
                    | TypedOperationResultLane::WindowTransient
            ) && !self.pending_artifact_publication.as_mut().is_some_and(PendingArtifactStorePublication::acknowledge)
            {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.artifact-publication-ack"), "artifact-store result ACK lost its exact pending publication authority"));
            }
            if lane == TypedOperationResultLane::Child && !self.pending_child_publication.as_mut().is_some_and(PendingChildGroupPublication::acknowledge) {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-publication-ack"), "child-group result ACK lost its exact committed publication authority"));
            }
            self.result_page = None;
            self.result_page_presented = false;
            self.result_sequence = self.result_sequence.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.result-sequence"), "typed-operation result sequence exhausted"))?;
            self.stage = if matches!(lane, TypedOperationResultLane::Terminal | TypedOperationResultLane::Fault | TypedOperationResultLane::Download) {
                MountedTypedCommandFullOperationStage::Retiring
            } else {
                MountedTypedCommandFullOperationStage::Publishing
            };
            Ok(true)
        }

        fn retire_string_scalar(value: &mut String, maximum_bytes: usize) -> Option<PluginCloseStep> {
            let scalar_bytes = value.chars().next_back()?.len_utf8();
            if scalar_bytes > maximum_bytes {
                return Some(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            value.pop();
            Some(PluginCloseStep::Pending { released_items: 0, released_bytes: scalar_bytes })
        }

        fn retirement_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if self.stage != MountedTypedCommandFullOperationStage::Retiring {
                return Ok(PluginCloseStep::Blocked { reason: "typed operation is not admitted for retirement" });
            }
            if self.result_page.is_some() {
                return Ok(PluginCloseStep::Blocked { reason: "typed operation retains an unacknowledged result page" });
            }
            if let Some(pending) = self.pending_artifact_publication.as_mut() {
                pending.begin_close();
                let step = pending.close_step(maximum_items, maximum_bytes)?;
                if step == store::SnapshotRetirementStep::Complete {
                    if !pending.terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.artifact-publication-terminal"), "artifact-store publication reported complete without terminal emptiness"));
                    }
                    self.pending_artifact_publication = None;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(match step {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } => PluginCloseStep::Pending { released_items, released_bytes },
                    store::SnapshotRetirementStep::Blocked => PluginCloseStep::Blocked { reason: "artifact-store publication close is blocked" },
                    store::SnapshotRetirementStep::Complete => unreachable!("handled terminal artifact-store publication"),
                });
            }
            if let Some(pending) = self.pending_child_publication.as_mut() {
                pending.begin_close();
                let step = pending.close_step(maximum_items, maximum_bytes);
                if step == PluginCloseStep::Complete {
                    if !pending.terminal_is_empty() {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.child-publication-terminal"), "child-group publication reported complete without terminal emptiness"));
                    }
                    self.pending_child_publication = None;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if let Some(publication) = self.publication.as_mut() {
                match publication {
                    ArtifactToolCompletionValue::Emit(Ok(emit), ephemeral) => {
                        if let Some(child) = emit.child_emits.last_mut() {
                            let step = child.close_one(maximum_items, maximum_bytes);
                            if step == PluginCloseStep::Complete {
                                emit.child_emits.pop();
                                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                            }
                            return Ok(step);
                        }
                        if maximum_items != 0 {
                            if emit.artifact_mutations.pop().is_some()
                                || emit.config_mutations.pop().is_some()
                                || emit.draft_mutations.pop().is_some()
                                || ephemeral.presence.pop().is_some()
                                || ephemeral.transient.pop().is_some()
                                || ephemeral.window_transient.pop().is_some()
                                || emit.effects.pop().is_some()
                                || emit.extension_invocations.pop().is_some()
                                || emit.events.pop().is_some()
                            {
                                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                            }
                            if emit.tasks.pop().is_some() {
                                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                            }
                        }
                        if maximum_items == 0 {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                    }
                    ArtifactToolCompletionValue::Download(Ok(download), ephemeral) => {
                        if maximum_items != 0 && (ephemeral.presence.pop().is_some() || ephemeral.transient.pop().is_some() || ephemeral.window_transient.pop().is_some()) {
                            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                        }
                        if download.chunks.chunks_remaining() != 0 && (maximum_items == 0 || maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES) {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                        if let Some(chunk) = download.chunks.close_take_chunk()? {
                            let bytes = chunk.len();
                            drop(chunk);
                            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
                        }
                        if !download.filename.is_empty() {
                            return Ok(Self::retire_string_scalar(&mut download.filename, maximum_bytes).expect("nonempty filename"));
                        }
                        if !download.mime_type.is_empty() {
                            return Ok(Self::retire_string_scalar(&mut download.mime_type, maximum_bytes).expect("nonempty MIME type"));
                        }
                        if let Some(encoding) = download.encoding.as_mut().filter(|value| !value.is_empty()) {
                            return Ok(Self::retire_string_scalar(encoding, maximum_bytes).expect("nonempty encoding"));
                        }
                        if maximum_items == 0 {
                            return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                        }
                    }
                    ArtifactToolCompletionValue::Emit(Err(_), _) | ArtifactToolCompletionValue::Download(Err(_), _) if maximum_items == 0 => {
                        return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                    }
                    ArtifactToolCompletionValue::Emit(Err(_), _) | ArtifactToolCompletionValue::Download(Err(_), _) => {}
                }
                self.publication = None;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(raw_input) = self.raw_input.as_ref() {
                let step = raw_input.close_step(maximum_items.min(1), maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    return Ok(step);
                }
                if !raw_input.terminal_is_empty() {
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.raw-page-terminal"), "typed-operation raw page owner reported Complete without terminal emptiness"));
                }
                self.raw_input = None;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(chunks) = self.output_chunks.as_ref() {
                if chunks.chunks_remaining() != 0 && (maximum_items == 0 || maximum_bytes < ARTIFACT_OUTPUT_CHUNK_BYTES) {
                    return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
                }
                if let Some(chunk) = chunks.close_take_chunk()? {
                    let bytes = chunk.len();
                    drop(chunk);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: bytes });
                }
            }
            if maximum_items == 0 && (self.output_chunks.is_some() || self.completion.is_some() || self.cancellation_lease.is_some()) {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if self.output_chunks.take().is_some() || self.completion.take().is_some() {
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.captured_child_content.take().is_some() {
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(mut lease) = self.cancellation_lease.take() {
                lease.finish_in_place();
                drop(lease);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            Ok(PluginCloseStep::Complete)
        }

        fn terminal_is_empty(&self) -> bool {
            self.stage == MountedTypedCommandFullOperationStage::Retiring
                && self.session.is_none()
                && self.session_rejected.is_none()
                && self.terminal_outcome.is_none()
                && self.publication.is_none()
                && self.pending_artifact_publication.is_none()
                && self.pending_child_publication.is_none()
                && self.captured_child_content.is_none()
                && self.result_page.is_none()
                && self.raw_input.is_none()
                && self.output_chunks.is_none()
                && self.completion.is_none()
                && self.cancellation_lease.is_none()
        }
    }

    fn bounded_json_items(value: Option<&DslValue>, maximum: usize) -> Result<usize, Fault> {
        let mut count = 1usize;
        let mut pending = value.into_iter().collect::<Vec<_>>();
        while let Some(value) = pending.pop() {
            count = count.checked_add(1).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), "decoded item count overflowed"))?;
            if count > maximum {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), format!("decoded command contains {count} items; maximum is {maximum}")));
            }
            match value {
                DslValue::Array(values) => pending.extend(values),
                DslValue::Object(values) => {
                    count = count.checked_add(values.len()).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), "decoded item count overflowed"))?;
                    if count > maximum {
                        return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.decoded-limit"), format!("decoded command contains {count} items; maximum is {maximum}")));
                    }
                    pending.extend(values.iter().map(|(_, value)| value));
                }
                _ => {}
            }
        }
        Ok(count)
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum TypedCommandFullOperationPhase {
        Prepare,
        Reducer,
        Fault,
    }

    pub(crate) struct TypedCommandFullOperationJob<A: ArtifactApp> {
        operation: Option<semio_framework_job::Operation>,
        parent_document_id: Option<String>,
        command: Option<std::sync::Arc<A::Command>>,
        snapshot: Option<std::sync::Arc<A::Snapshot>>,
        config: Option<std::sync::Arc<A::Config>>,
        history: Option<std::sync::Arc<HistoryView>>,
        children: Option<std::sync::Arc<ChildContentView>>,
        draft: Option<std::sync::Arc<A::Draft>>,
        interaction_state: Option<std::sync::Arc<protocol::InteractionState>>,
        interaction_hover: Option<std::sync::Arc<InteractionHoverState>>,
        peer_presence: Option<std::sync::Arc<PeerPresenceRoot>>,
        presence_local: Option<store::SnapshotRead<A::Presence>>,
        presence_peers: Option<std::sync::Arc<store::PresencePeersRoot<A::Presence>>>,
        transient: Option<std::sync::Arc<A::Transient>>,
        contract: semio_framework::ToolExecutionContract,
        decoded_items: usize,
        phase: TypedCommandFullOperationPhase,
        prepare_cursor: u8,
        reducer_cursor: u8,
        output: Option<ArtifactToolCompletion<A>>,
        closing: bool,
    }

    impl<A: ArtifactApp> TypedCommandFullOperationJob<A> {
        fn checkpoint(&self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::Checkpoint {
            let state = [self.phase as u8, self.prepare_cursor, self.reducer_cursor];
            semio_framework_job::Checkpoint { state: retained_job_payload(cx, semio_framework_job::JobPayloadStream::CheckpointState, &state), applied_progress: u64::from(self.prepare_cursor).saturating_add(u64::from(self.reducer_cursor)) }
        }

        fn fault(&mut self, cx: &mut semio_framework_job::StepContext<'_>, message: &[u8]) -> semio_framework_job::StepOutcome {
            self.phase = TypedCommandFullOperationPhase::Fault;
            semio_framework_job::StepOutcome::Fault(semio_framework_job::JobFault { detail: retained_job_payload(cx, semio_framework_job::JobPayloadStream::Fault, message) })
        }
    }

    impl<A: ArtifactApp> semio_framework_job::InteractiveJob for TypedCommandFullOperationJob<A> {
        fn step(&mut self, cx: &mut semio_framework_job::StepContext<'_>) -> semio_framework_job::StepOutcome {
            if cx.is_cancelled() {
                return semio_framework_job::StepOutcome::Cancelled;
            }
            if cx.should_yield() || cx.fuel_remaining() == 0 {
                return semio_framework_job::StepOutcome::Yield;
            }
            if self.decoded_items > self.contract.max_decoded_items || self.contract.max_work_units_per_step == 0 || self.contract.max_output_bytes == 0 {
                return self.fault(cx, b"typed command admission exceeds its fixed item, work, or output cap");
            }
            cx.consume_fuel(1);
            let operation = self.operation.expect("tool job factory assigns operation identity");
            debug_assert_eq!(operation.operation, cx.operation());
            match self.phase {
                TypedCommandFullOperationPhase::Prepare => {
                    cx.set_stage("typed-command-prepare");
                    let present = match self.prepare_cursor {
                        0 => self.parent_document_id.is_some(),
                        1 => self.command.is_some(),
                        2 => self.snapshot.is_some(),
                        3 => self.config.is_some(),
                        4 => self.history.is_some(),
                        5 => self.children.is_some(),
                        6 => self.draft.is_some(),
                        7 => self.interaction_state.is_some(),
                        8 => self.interaction_hover.is_some(),
                        9 => self.peer_presence.is_some(),
                        10 => self.presence_local.is_some(),
                        11 => self.presence_peers.is_some(),
                        12 => self.transient.is_some(),
                        _ => {
                            self.phase = TypedCommandFullOperationPhase::Reducer;
                            return semio_framework_job::StepOutcome::CheckpointReady(self.checkpoint(cx));
                        }
                    };
                    if !present {
                        return self.fault(cx, b"typed command preparation root is absent");
                    }
                    self.prepare_cursor = self.prepare_cursor.saturating_add(1);
                    if self.prepare_cursor == 1 {
                        semio_framework_job::StepOutcome::PreviewReady(retained_job_payload(cx, semio_framework_job::JobPayloadStream::Preview, b"typed-command-prepare"))
                    } else {
                        semio_framework_job::StepOutcome::CheckpointReady(self.checkpoint(cx))
                    }
                }
                TypedCommandFullOperationPhase::Reducer => {
                    cx.set_stage("typed-command-reducer");
                    self.reducer_cursor = self.reducer_cursor.saturating_add(1);
                    self.fault(cx, b"generic bounded proof has no resumable app-owned reducer job")
                }
                TypedCommandFullOperationPhase::Fault => self.fault(cx, b"typed command remains faulted"),
            }
        }

        fn begin_close(&mut self) {
            self.closing = true;
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> semio_framework_job::InteractiveJobCloseStep {
            self.closing = true;
            if let Some(parent) = self.parent_document_id.as_ref() {
                if maximum_items == 0 || maximum_bytes < parent.len() {
                    return semio_framework_job::InteractiveJobCloseStep::Pending { released_items: 0, released_bytes: 0 };
