    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct ArtifactEnvelopeDecodeOperationHandle {
        pub operation: semio_framework_job::OperationId,
        pub generation: semio_framework_job::Generation,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum ArtifactEnvelopeDecodeOperationPoll {
        Pending,
        Progress,
        Ready,
        Cancelled,
        Fault,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ActiveArtifactEnvelopeDecodeState {
        Active,
        Ready,
        ClosingCancelled,
        ClosingFault,
        Complete,
    }

    struct ActiveArtifactEnvelopeDecode<P: Send + 'static, Mutation: Send + 'static> {
        operation: semio_framework_job::OperationId,
        generation: semio_framework_job::Generation,
        cancel: semio_framework_job::CancelToken,
        session: std::mem::ManuallyDrop<Option<semio_framework_job::MountedWorkerJobSession<store::ArtifactEnvelopeDecodeAuthority<P, Mutation>>>>,
        session_rejected: std::mem::ManuallyDrop<Option<semio_framework_job::WorkerJobSessionAdmissionRejected<store::ArtifactEnvelopeDecodeAuthority<P, Mutation>>>>,
        retained_outcome: std::mem::ManuallyDrop<Option<semio_framework_job::StepOutcome>>,
        terminal_state: Option<ActiveArtifactEnvelopeDecodeState>,
        rejected: std::mem::ManuallyDrop<Option<Box<dyn store::ErasedSnapshotRetirement>>>,
        completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>,
        completed_close_requested: bool,
        state: ActiveArtifactEnvelopeDecodeState,
    }

    impl<P, Mutation> ActiveArtifactEnvelopeDecode<P, Mutation>
    where
        P: Send + 'static,
        Mutation: Send + 'static,
    {
        fn admitted(operation: semio_framework_job::OperationId, generation: semio_framework_job::Generation, decode: store::ArtifactEnvelopeDecodeAuthority<P, Mutation>, completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>) -> Self {
            let cancel = semio_framework_job::CancelToken::root_now();
            let params = semio_framework_job::BatchJobParams {
                operation,
                generation,
                cancel: cancel.clone(),
                config: semio_framework_job::BatchDriveConfig { site: "artifact_envelope_decode", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 64, step_budget_us: semio_framework_job::INTERACTIVE_LANE_WALL_US },
                now_us: semio_framework_job::default_now_us,
            };
            let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new(decode, params) {
                Ok(session) => (Some(session), None),
                Err(rejected) => (None, Some(rejected)),
            };
            Self {
                operation,
                generation,
                cancel,
                session: std::mem::ManuallyDrop::new(session),
                session_rejected: std::mem::ManuallyDrop::new(session_rejected),
                retained_outcome: std::mem::ManuallyDrop::new(None),
                terminal_state: None,
                rejected: std::mem::ManuallyDrop::new(None),
                completion,
                completed_close_requested: false,
                state: ActiveArtifactEnvelopeDecodeState::Active,
            }
        }

        fn rejected(operation: semio_framework_job::OperationId, generation: semio_framework_job::Generation, rejected: Box<dyn store::ErasedSnapshotRetirement>, completion: std::sync::Arc<store::ArtifactEnvelopeDecodeCompletion>) -> Self {
            Self {
                operation,
                generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                session: std::mem::ManuallyDrop::new(None),
                session_rejected: std::mem::ManuallyDrop::new(None),
                retained_outcome: std::mem::ManuallyDrop::new(None),
                terminal_state: None,
                rejected: std::mem::ManuallyDrop::new(Some(rejected)),
                completion,
                completed_close_requested: false,
                state: ActiveArtifactEnvelopeDecodeState::ClosingFault,
            }
        }

        fn request_completed_close(&mut self, completed: &store::ArtifactEnvelopeCompletedRecordRegistry<P, Mutation>) -> Result<bool, Fault> {
            let Some(ticket) = self.completion.ticket() else { return Ok(true) };
            if !self.completed_close_requested {
                match completed.try_request_close(ticket) {
                    Ok(()) => self.completed_close_requested = true,
                    Err(store::ArtifactEnvelopeCompletedRecordFault::Contended) => return Ok(false),
                    Err(store::ArtifactEnvelopeCompletedRecordFault::Stale) if completed.ticket_reclaimed(ticket) => return Ok(true),
                    Err(_) => return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.completed-close"), "completed envelope result lost its exact close authority")),
                }
            }
            Ok(completed.ticket_reclaimed(ticket))
        }

        /// 🔎 The detail page is the only record of WHY a live decode failed; it retires
        /// with the outcome, so it is reported here before the close loop releases it.
        fn drive(
            &mut self,
            pool: &semio_framework_async::WorkerPool,
            live_generation: semio_framework_job::Generation,
            completed: &store::ArtifactEnvelopeCompletedRecordRegistry<P, Mutation>,
            maximum_items: usize,
            maximum_bytes: usize,
        ) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(rejected) = self.session_rejected.as_mut() {
                return match rejected.close_step(maximum_items.min(1), maximum_bytes) {
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::InteractiveJobCloseStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "envelope worker admission rejection is temporarily blocked" }),
                    semio_framework_job::InteractiveJobCloseStep::Complete if rejected.terminal_is_empty() => {
                        drop(self.session_rejected.take());
                        self.state = ActiveArtifactEnvelopeDecodeState::ClosingFault;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::InteractiveJobCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-rejected-false-terminal"), "rejected envelope worker session reported Complete without terminal-empty authority"))
                    }
                };
            }
            if let Some(rejected) = self.rejected.as_mut() {
                let step = rejected.close_step(maximum_items.min(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))?;
                return match step {
                    store::SnapshotRetirementStep::Complete if rejected.terminal_is_empty() => {
                        drop(self.rejected.take());
                        self.state = ActiveArtifactEnvelopeDecodeState::Complete;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    store::SnapshotRetirementStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.rejected-false-terminal"), "rejected envelope owner reported Complete without terminal-empty authority")),
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "rejected envelope owner is temporarily blocked" }),
                };
            }
            if live_generation != self.generation && self.state == ActiveArtifactEnvelopeDecodeState::Active {
                self.cancel.cancel_now();
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready && self.cancel.is_cancelled_now() {
                self.state = ActiveArtifactEnvelopeDecodeState::ClosingCancelled;
            }
            if matches!(self.state, ActiveArtifactEnvelopeDecodeState::ClosingCancelled | ActiveArtifactEnvelopeDecodeState::ClosingFault) {
                if self.request_completed_close(completed)? {
                    self.state = ActiveArtifactEnvelopeDecodeState::Complete;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(PluginCloseStep::Blocked { reason: "cancelled envelope output awaits the completed-record close pump" });
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Complete {
                if self.session.as_ref().is_some_and(|session| session.terminal_is_empty()) {
                    drop(self.session.take());
                    self.terminal_state = None;
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                if self.decode_worker_owners_are_terminal() {
                    return Ok(PluginCloseStep::Complete);
                }
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready && self.terminal_state.is_none() && self.retained_outcome.is_none() && self.session.is_none() {
                return Ok(PluginCloseStep::Blocked { reason: "decoded envelope awaits exact consumer publication" });
            }
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready {
                if let Some(session) = self.session.as_mut() {
                    if session.terminal_is_empty() {
                        drop(self.session.take());
                        self.terminal_state = None;
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                }
            }
            if let Some(outcome) = self.retained_outcome.as_mut() {
                return match outcome.close_step(maximum_items.min(1), maximum_bytes) {
                    semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::JobPayloadCloseStep::Complete if outcome.terminal_is_empty() => {
                        drop(self.retained_outcome.take());
                        if self.terminal_state.is_none() {
                            self.session
                                .as_mut()
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-missing"), "live envelope decode lost its retained worker session"))?
                                .resume()
                                .map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.resume"), "envelope worker outcome lost its exact resume authority"))?;
                        }
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::JobPayloadCloseStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.outcome-false-terminal"), "envelope worker outcome reported Complete without terminal-empty payload")),
                };
            }
            if let Some(target) = self.terminal_state {
                let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-missing"), "terminal envelope decode lost its retained worker session"))?;
                session.begin_close();
                return match session.close_step(maximum_items.min(1), maximum_bytes) {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::WorkerJobCloseStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "terminal envelope worker close is temporarily blocked" }),
                    semio_framework_job::WorkerJobCloseStep::Complete if session.terminal_is_empty() => {
                        drop(self.session.take());
                        self.terminal_state = None;
                        if self.state != ActiveArtifactEnvelopeDecodeState::Ready {
                            self.state = target;
                        }
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::WorkerJobCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-false-terminal"), "terminal envelope worker session reported Complete without terminal-empty authority"))
                    }
                };
            }
            let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.session-missing"), "live envelope decode lost its retained worker session"))?;
            match session.pump_one_for_interactive_turn(pool, semio_framework_async::Lane::Interactive) {
                Ok(semio_framework_job::WorkerJobPoll::Outcome | semio_framework_job::WorkerJobPoll::Terminal) => {
                    let outcome = session.take_checked_out_outcome().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-envelope.outcome-missing"), "envelope worker checkout lost its exact outcome"))?;
                    self.terminal_state = match &outcome {
                        semio_framework_job::StepOutcome::Complete(_) if self.completion.ticket().is_some() => {
                            self.state = ActiveArtifactEnvelopeDecodeState::Ready;
                            Some(ActiveArtifactEnvelopeDecodeState::Ready)
                        }
                        semio_framework_job::StepOutcome::Cancelled => Some(ActiveArtifactEnvelopeDecodeState::ClosingCancelled),
                        semio_framework_job::StepOutcome::Fault(fault) => {
                            eprintln!("[TRACE] live envelope decode faulted: {}", String::from_utf8_lossy(fault.detail.page(0).unwrap_or(&[])));
                            Some(ActiveArtifactEnvelopeDecodeState::ClosingFault)
                        }
                        semio_framework_job::StepOutcome::Complete(_) => Some(ActiveArtifactEnvelopeDecodeState::ClosingFault),
                        _ => None,
                    };
                    *self.retained_outcome = Some(outcome);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Ok(semio_framework_job::WorkerJobPoll::Submitted | semio_framework_job::WorkerJobPoll::Idle) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                Ok(_) => Ok(PluginCloseStep::Blocked { reason: "envelope worker awaits its mounted wake" }),
                Err(_) => Ok(PluginCloseStep::Blocked { reason: "envelope worker lane is saturated or contended" }),
            }
        }

        fn decode_worker_owners_are_terminal(&self) -> bool {
            self.session.is_none() && self.retained_outcome.is_none() && self.session_rejected.is_none() && self.rejected.is_none() && self.terminal_state.is_none()
        }

        /// 🧹️ Closes the parked worker session/outcome ladder after [`Self::state`] reached
        /// [`ActiveArtifactEnvelopeDecodeState::Ready`] so store replacement can retire the decode owner.
        fn force_worker_session_terminal(&mut self, maximum_items: usize, maximum_bytes: usize, budget: usize) -> bool {
            for _ in 0..budget {
                if let Some(target) = self.terminal_state {
                    let Some(session) = self.session.as_mut() else {
                        return false;
                    };
                    session.begin_close();
                    match session.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::WorkerJobCloseStep::Pending { .. } => continue,
                        semio_framework_job::WorkerJobCloseStep::Blocked => continue,
                        semio_framework_job::WorkerJobCloseStep::Complete if session.terminal_is_empty() => {
                            drop(self.session.take());
                            self.terminal_state = None;
                            if self.state != ActiveArtifactEnvelopeDecodeState::Ready {
                                self.state = target;
                            }
                        }
                        semio_framework_job::WorkerJobCloseStep::Complete => continue,
                    }
                    continue;
                }
                if let Some(outcome) = self.retained_outcome.as_mut() {
                    match outcome.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::JobPayloadCloseStep::Pending { .. } => continue,
                        semio_framework_job::JobPayloadCloseStep::Complete if outcome.terminal_is_empty() => {
                            drop(self.retained_outcome.take());
                            if self.terminal_state.is_none() {
                                if let Some(session) = self.session.as_mut() {
                                    let _ = session.resume();
                                }
                            }
                        }
                        semio_framework_job::JobPayloadCloseStep::Complete => return false,
                    }
                    continue;
                }
                if let Some(session) = self.session.as_mut() {
                    if session.terminal_is_empty() {
                        drop(self.session.take());
                        self.terminal_state = None;
                        continue;
                    }
                    let poll = session.poll();
                    if session.checked_out_outcome().is_some() || poll == semio_framework_job::WorkerJobPoll::CheckedOut {
                        session.begin_close();
                    } else if !matches!(poll, semio_framework_job::WorkerJobPoll::Closing | semio_framework_job::WorkerJobPoll::TerminalEmpty) {
                        session.begin_close();
                    }
                    match session.close_step(maximum_items.min(1), maximum_bytes) {
                        semio_framework_job::WorkerJobCloseStep::Pending { .. } => continue,
                        semio_framework_job::WorkerJobCloseStep::Blocked => continue,
                        semio_framework_job::WorkerJobCloseStep::Complete => {
                            if session.terminal_is_empty() {
                                drop(self.session.take());
                                self.terminal_state = None;
                            }
                        }
                    }
                    continue;
                }
                return self.decode_worker_owners_are_terminal();
            }
            self.decode_worker_owners_are_terminal()
        }

        /// 🏃️ Whether one more `drive` can advance this decode. A `Ready` decode still runs until its
        /// worker session, retained outcome, and terminal close target are empty — only then does it
        /// park awaiting exact consumer publication.
        fn has_runnable_work(&self) -> bool {
            if self.state == ActiveArtifactEnvelopeDecodeState::Ready {
                return self.terminal_state.is_some() || self.retained_outcome.is_some() || self.session.as_ref().is_some_and(|session| !session.terminal_is_empty());
            }
            self.state != ActiveArtifactEnvelopeDecodeState::Ready
        }

        /// 📊️ A decode cancelled after its worker finished is Cancelled, never Ready: maintenance closes
        /// its completed record, so no consumer may admit it in between.
        fn poll(&self) -> ArtifactEnvelopeDecodeOperationPoll {
            match self.state {
                ActiveArtifactEnvelopeDecodeState::Active => ArtifactEnvelopeDecodeOperationPoll::Pending,
                ActiveArtifactEnvelopeDecodeState::Ready if self.cancel.is_cancelled_now() => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactEnvelopeDecodeState::Ready => ArtifactEnvelopeDecodeOperationPoll::Ready,
                ActiveArtifactEnvelopeDecodeState::ClosingCancelled => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactEnvelopeDecodeState::ClosingFault => ArtifactEnvelopeDecodeOperationPoll::Fault,
                ActiveArtifactEnvelopeDecodeState::Complete if self.cancel.is_cancelled_now() => ArtifactEnvelopeDecodeOperationPoll::Cancelled,
                ActiveArtifactEnvelopeDecodeState::Complete => ArtifactEnvelopeDecodeOperationPoll::Fault,
            }
        }

        fn terminal_is_empty(&self, completed: &store::ArtifactEnvelopeCompletedRecordRegistry<P, Mutation>) -> bool {
            let output_terminal = self.completion.ticket().is_none_or(|ticket| completed.ticket_reclaimed(ticket));
            self.state == ActiveArtifactEnvelopeDecodeState::Complete && self.session.is_none() && self.session_rejected.is_none() && self.retained_outcome.is_none() && self.rejected.is_none() && output_terminal
        }
    }

    impl<P: Send + 'static, Mutation: Send + 'static> Drop for ActiveArtifactEnvelopeDecode<P, Mutation> {
        fn drop(&mut self) {
            assert!(
                std::thread::panicking() || self.session.is_none() && self.session_rejected.is_none() && self.retained_outcome.is_none() && self.rejected.is_none() && self.state == ActiveArtifactEnvelopeDecodeState::Complete,
                "active envelope decode reached Drop before its worker and rejected owner were terminal empty"
            );
        }
    }

    struct ActiveArtifactEnvelopeIngress {
        pages: std::mem::ManuallyDrop<Option<store::OwnedSchemaDecodePages>>,
        closing: bool,
    }

    impl ActiveArtifactEnvelopeIngress {
        fn new(pages: store::OwnedSchemaDecodePages) -> Self {
            Self { pages: std::mem::ManuallyDrop::new(Some(pages)), closing: false }
        }

        fn take_pages(&mut self) -> Option<store::OwnedSchemaDecodePages> {
            self.pages.take()
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            let Some(pages) = self.pages.as_mut() else { return PluginCloseStep::Complete };
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(page) = pages.close_take_page() {
                let released_bytes = page.len();
                if released_bytes > maximum_bytes {
                    pages.admit_page(page).expect("an exact ingress page returns to its pre-admitted slot when the close byte grant is insufficient");
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                return PluginCloseStep::Pending { released_items: 1, released_bytes };
            }
            let pages = self.pages.take().expect("terminal ingress pages remain retained");
            assert!(pages.terminal_is_empty());
            drop(pages);
            PluginCloseStep::Complete
        }

        fn terminal_is_empty(&self) -> bool {
            self.pages.is_none()
        }
    }

    impl Drop for ActiveArtifactEnvelopeIngress {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "artifact envelope ingress reached Drop before every admitted page was transferred or bounded-closed");
        }
    }

    /// 🔐️ Performs the sole document-store swap only inside its fresh authority decision.
    #[expect(clippy::result_large_err, reason = "A rejected publication returns the unchanged candidate store, preserving its existing bounded retirement authority.")]
    pub fn publish_document_store_candidate_if_authoritative<P, Mutation>(
        live: &mut ArtifactStore<P, Mutation>,
        candidate: ArtifactStore<P, Mutation>,
        validate: impl FnOnce() -> Result<(), Fault>,
    ) -> Result<ArtifactStore<P, Mutation>, (Fault, ArtifactStore<P, Mutation>)>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        if let Err(fault) = validate() {
            return Err((fault, candidate));
        }
        Ok(std::mem::replace(live, candidate))
    }

    /// 🔄️ Publishes the replacement owner's heap candidate without moving either complete Store
    /// through the maintenance stack; the returned box owns the displaced live Store in place.
    fn publish_boxed_document_store_candidate_if_authoritative<P, Mutation>(
        live: &mut ArtifactStore<P, Mutation>,
        mut candidate: Box<ArtifactStore<P, Mutation>>,
        validate: impl FnOnce() -> Result<(), Fault>,
    ) -> Result<Box<ArtifactStore<P, Mutation>>, (Fault, Box<ArtifactStore<P, Mutation>>)>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        if let Err(fault) = validate() {
            return Err((fault, candidate));
        }
        std::mem::swap(live, candidate.as_mut());
        Ok(candidate)
    }

    struct CompositionPinsRetirement {
        pins: std::mem::ManuallyDrop<Option<Vec<vcs::CompositionPin>>>,
        active: std::mem::ManuallyDrop<Option<vcs::CompositionPin>>,
        field: u8,
    }

    impl CompositionPinsRetirement {
        fn new(pins: Vec<vcs::CompositionPin>) -> Self {
            Self { pins: std::mem::ManuallyDrop::new(Some(pins)), active: std::mem::ManuallyDrop::new(None), field: 0 }
        }

        fn active_string_mut(&mut self) -> Option<&mut String> {
            let pin = self.active.as_mut()?;
            match self.field {
                0 => Some(&mut pin.child_ref.artifact_id),
                1 => Some(&mut pin.child_ref.dialect.artifact_kind),
                2 => Some(&mut pin.child_ref.dialect.standard),
                3 => Some(&mut pin.child_ref.dialect.subset),
                4 => Some(&mut pin.checkpoint_id),
                _ => None,
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if self.active.is_none() {
                if let Some(pin) = self.pins.as_mut().and_then(Vec::pop) {
                    *self.active = Some(pin);
                    self.field = 0;
                } else if let Some(pins) = self.pins.take() {
                    drop(pins);
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                } else {
                    return PluginCloseStep::Complete;
                }
            }
            while self.field < 5 && self.active_string_mut().is_some_and(|value| value.is_empty()) {
                self.field += 1;
            }
            if let Some(value) = self.active_string_mut() {
                let bytes = value.chars().next_back().map_or(0, char::len_utf8);
                if bytes > maximum_bytes {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                value.pop();
                return PluginCloseStep::Pending { released_items: 0, released_bytes: bytes };
            }
            drop(self.active.take());
            PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
        }

        fn terminal_is_empty(&self) -> bool {
            self.pins.is_none() && self.active.is_none()
        }
    }

    impl Drop for CompositionPinsRetirement {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "composition-pin retirement reached Drop before every displaced identity owner was bounded-closed");
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum ActiveArtifactStoreReplacementState {
        Initializing,
        AwaitingMembers,
        OpeningMembers,
        ClosingRejectedMember,
        ValidatingClosure,
        PreparingCandidateViews,
        CandidateReady,
        RetiringRejectedMembers,
        RetiringCommittedMembers,
        RetiringCommittedStore,
        RetiringRejectedCandidate,
        Complete,
    }

    /// 🧭️ Which leg of a document-archive replacement refused the candidate, and with what
    /// evidence. An atomic replacement validates three of them in order — the owned-member set
    /// (`members`), the recursive ownership `closure`, and the `retained-publication` guard plus the
    /// app's own publication `authority` — and every one of them used to collapse into a single
    /// `faulted: bool` whose only explanation was a `#[cfg(test)]` `eprintln!`. A headless host
    /// therefore saw one opaque sentence for eleven distinct causes. This carries the cause to the
    /// wire instead: {@link ArtifactStoreReplacementRefusal::into_fault} mints the leg-specific
    /// {@link FaultCode} and detail that `Effect::LoadDocument` reports to the shell.
    /// 🔖️ A bounded inline copy of a job fault's first detail page — the initializer's own
    /// refusal slug (e.g. `bounded-store.initializer-envelope-invalid`), which the replacement used
    /// to drop on the floor. Fixed capacity, no allocation, `Copy`: it rides the refusal record.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) struct ArtifactStoreRefusalCode {
        bytes: [u8; 96],
        len: u8,
    }

    impl ArtifactStoreRefusalCode {
        const EMPTY: Self = Self { bytes: [0; 96], len: 0 };

        fn from_page(page: &[u8]) -> Self {
            let mut bytes = [0u8; 96];
            let len = page.len().min(bytes.len());
            bytes[..len].copy_from_slice(&page[..len]);
            Self { bytes, len: len as u8 }
        }

        fn text(&self) -> &str {
            std::str::from_utf8(&self.bytes[..self.len as usize]).unwrap_or("<non-utf8 refusal page>")
        }
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum ArtifactStoreReplacementRefusal {
        Invariant { leg: ArtifactStoreReplacementLeg, detail: &'static str },
        InitializerAdmissionRejected,
        InitializerFailed(ArtifactStoreRefusalCode),
        Cancelled,
        MemberOpenRejected { ordinal: usize, diagnostic: store::MemberOpenDiagnostic },
        MemberIdentityMismatch { ordinal: usize, expected: usize },
        MemberFactoryRefused { ordinal: usize },
        ClosureRejected { diagnostic: store::OwnedDocumentClosureDiagnostic },
        ClosureMemberCount { members: usize, children: usize },
        PublicationGuard(ArtifactStoreReplacementPublicationGuard),
        PublicationAuthorityRejected,
    }

    /// 🦵️ The named leg a refusal belongs to — the same three the host message lists.
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub(crate) enum ArtifactStoreReplacementLeg {
        Initializer,
        Members,
        Closure,
        CandidateViews,
        RetainedPublication,
    }

    impl ArtifactStoreReplacementLeg {
        fn slug(self) -> &'static str {
            match self {
                Self::Initializer => "initializer",
                Self::Members => "members",
                Self::Closure => "closure",
                Self::CandidateViews => "candidate-views",
                Self::RetainedPublication => "retained-publication",
            }
        }
    }

    /// 🚦️ Every input the `CandidateReady` publication guard reads, as it read them.
    /// A bare "guard rejected" is unactionable; which of the seven conditions tripped is the answer.
    #[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
    pub(crate) struct ArtifactStoreReplacementPublicationGuard {
        pub(crate) closing: bool,
        pub(crate) cancelled: bool,
        pub(crate) parent_generation: u64,
        pub(crate) live_generation: u64,
        pub(crate) base_child_generation: u64,
        pub(crate) child_generation: u64,
        pub(crate) complete_candidate: bool,
        pub(crate) retirement_admitted: bool,
        pub(crate) next_generation: bool,
    }

    impl ArtifactStoreReplacementRefusal {
        fn leg(self) -> ArtifactStoreReplacementLeg {
            match self {
                Self::Invariant { leg, .. } => leg,
                Self::InitializerAdmissionRejected | Self::InitializerFailed(_) => ArtifactStoreReplacementLeg::Initializer,
                Self::Cancelled | Self::MemberOpenRejected { .. } | Self::MemberIdentityMismatch { .. } | Self::MemberFactoryRefused { .. } => ArtifactStoreReplacementLeg::Members,
                Self::ClosureRejected { .. } | Self::ClosureMemberCount { .. } => ArtifactStoreReplacementLeg::Closure,
                Self::PublicationGuard(_) | Self::PublicationAuthorityRejected => ArtifactStoreReplacementLeg::RetainedPublication,
            }
        }

        fn slug(self) -> &'static str {
            match self {
                Self::Invariant { .. } => "invariant",
                Self::InitializerAdmissionRejected => "initializer-admission-rejected",
                Self::InitializerFailed(_) => "initializer-failed",
                Self::Cancelled => "cancelled",
                Self::MemberOpenRejected { .. } => "member-open-rejected",
                Self::MemberIdentityMismatch { .. } => "member-identity-mismatch",
                Self::MemberFactoryRefused { .. } => "member-factory-refused",
                Self::ClosureRejected { .. } => "closure-rejected",
                Self::ClosureMemberCount { .. } => "closure-member-count",
                Self::PublicationGuard(_) => "publication-guard",
                Self::PublicationAuthorityRejected => "publication-authority-rejected",
            }
        }

        fn detail(self) -> String {
            match self {
                Self::Invariant { detail, .. } => detail.to_string(),
                Self::InitializerAdmissionRejected => "the app's document-store initialization job was refused admission to the interactive worker lane".to_string(),
                Self::InitializerFailed(code) => format!("the app's document-store initialization job faulted or was cancelled before it produced a candidate, reporting `{}`; its `build_document_store_initialization_job` refused this envelope, or the envelope's schema/id/history failed that job's own validation", code.text()),
                Self::Cancelled => "the replacement was cancelled before its member set reached candidate readiness".to_string(),
                Self::MemberOpenRejected { ordinal, diagnostic } => format!("owned member {ordinal} was rejected by its typed open ({diagnostic:?})"),
                Self::MemberIdentityMismatch { ordinal, expected } => format!("owned member open returned ordinal {ordinal} while the sealed set expected {expected}, or its artifact/owner reference changed across the open"),
                Self::MemberFactoryRefused { ordinal } => format!("the app's member factory refused the admitted open request for ordinal {ordinal}"),
                Self::ClosureRejected { diagnostic } => format!("recursive ownership closure validation rejected the candidate ({diagnostic:?})"),
                Self::ClosureMemberCount { members, children } => format!("closure validation reached {members} members while the candidate registry owns {children}; the archive's member roster is not the parent's exact owned closure"),
                Self::PublicationGuard(guard) => format!(
                    "the retained publication guard refused the ready candidate: closing={} cancelled={} parent-generation={} live-generation={} base-child-generation={} child-generation={} complete-candidate={} retirement-admitted={} next-generation={}",
                    guard.closing,
                    guard.cancelled,
                    guard.parent_generation,
                    guard.live_generation,
                    guard.base_child_generation,
                    guard.child_generation,
                    guard.complete_candidate,
                    guard.retirement_admitted,
                    guard.next_generation,
                ),
                Self::PublicationAuthorityRejected => "the app's `validate_document_store_publication` refused the exact candidate".to_string(),
            }
        }

        /// 🧯️ The typed fault the host reports instead of the one-sentence collapse.
        pub(crate) fn into_fault(self) -> Fault {
            let leg = self.leg();
            Fault::new(FaultOrigin::Plugin, FaultCode::new(format!("plugin.internal.document-archive-replacement.{}", self.slug())), format!("document archive replacement failed its {} leg: {}", leg.slug(), self.detail()))
        }
    }

    pub(crate) struct ActiveArtifactStoreReplacement<P, Mutation, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
        M: SpaceMember + MemberFactory,
    {
        operation: semio_framework_job::OperationId,
        generation: semio_framework_job::Generation,
        base_child_content_generation: u64,
        cancel: semio_framework_job::CancelToken,
        cancel_signal: std::sync::Arc<std::sync::atomic::AtomicBool>,
        session: std::mem::ManuallyDrop<Option<semio_framework_job::MountedWorkerJobSession<ArtifactStoreInitializationJob<P, Mutation>>>>,
        session_rejected: std::mem::ManuallyDrop<Option<semio_framework_job::WorkerJobSessionAdmissionRejected<ArtifactStoreInitializationJob<P, Mutation>>>>,
        retained_outcome: std::mem::ManuallyDrop<Option<semio_framework_job::StepOutcome>>,
        terminal_target: Option<ActiveArtifactStoreReplacementState>,
        retained_store: std::mem::ManuallyDrop<Option<Box<ArtifactStore<P, Mutation>>>>,
        retained_disposer: std::mem::ManuallyDrop<ArtifactDisposal<ArtifactStore<P, Mutation>>>,
        member_ingress: std::mem::ManuallyDrop<Option<OwnedDocumentMemberIngressRegistry>>,
        active_member_ingress: std::mem::ManuallyDrop<Option<OwnedDocumentMemberIngress>>,
        pub(crate) active_member_open: std::mem::ManuallyDrop<Option<M::Open>>,
        candidate_children: std::mem::ManuallyDrop<Option<ChildMemberRegistry<M>>>,
        candidate_content: std::mem::ManuallyDrop<Option<ChildContentView>>,
        candidate_content_retirement: std::mem::ManuallyDrop<Option<ChildContentRetirement>>,
        displaced_content_retirements: std::mem::ManuallyDrop<Option<ArtifactFixedRegistry<ChildContentRetirement>>>,
        displaced_content_retirement_cursor: usize,
        candidate_composition: std::mem::ManuallyDrop<Option<CompositionCoordinator>>,
        displaced_pins: std::mem::ManuallyDrop<Option<CompositionPinsRetirement>>,
        retiring_child: std::mem::ManuallyDrop<Option<ChildMemberRetirement<M>>>,
        retiring_child_cursor: usize,
        next_member_ordinal: usize,
        view_member_ordinal: usize,
        candidate_source_generation: u64,
        member_step_sequence: u64,
        expires_at_us: u64,
        closure: Option<store::OwnedDocumentClosure>,
        pub(crate) committed: bool,
        refusal: Option<ArtifactStoreReplacementRefusal>,
        /// 📈️ The initializer's last reported `(operations folded, operations to fold)` (gap N17), kept after its handoff.
        pub(crate) fold_progress: (u64, u64),
        pub(crate) state: ActiveArtifactStoreReplacementState,
    }

    impl<P, Mutation, M> ActiveArtifactStoreReplacement<P, Mutation, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
        M: SpaceMember + MemberFactory,
    {
        pub(crate) fn new(operation: semio_framework_job::OperationId, generation: semio_framework_job::Generation, base_child_content_generation: u64, job: ArtifactStoreInitializationJob<P, Mutation>) -> Self {
            let cancel = semio_framework_job::CancelToken::root_now();
            let cancel_signal = job.cancel_signal();
            let params = semio_framework_job::BatchJobParams {
                operation,
                generation,
                cancel: semio_framework_job::CancelToken::root_now(),
                config: semio_framework_job::BatchDriveConfig { site: "artifact_store_replacement", stage: semio_framework_job::InteractiveStage::InteractiveStep, fuel_per_step: 64, step_budget_us: semio_framework_job::INTERACTIVE_LANE_WALL_US },
                now_us: semio_framework_job::default_now_us,
            };
            let (session, session_rejected) = match semio_framework_job::MountedWorkerJobSession::try_new(job, params) {
                Ok(session) => (Some(session), None),
                Err(rejected) => (None, Some(rejected)),
            };
            Self {
                operation,
                generation,
                base_child_content_generation,
                cancel,
                cancel_signal,
                session: std::mem::ManuallyDrop::new(session),
                session_rejected: std::mem::ManuallyDrop::new(session_rejected),
                retained_outcome: std::mem::ManuallyDrop::new(None),
                terminal_target: None,
                retained_store: std::mem::ManuallyDrop::new(None),
                retained_disposer: std::mem::ManuallyDrop::new(None),
                member_ingress: std::mem::ManuallyDrop::new(None),
                active_member_ingress: std::mem::ManuallyDrop::new(None),
                active_member_open: std::mem::ManuallyDrop::new(None),
                candidate_children: std::mem::ManuallyDrop::new(Some(ChildMemberRegistry::new())),
                candidate_content: std::mem::ManuallyDrop::new(Some(ChildContentView::EMPTY)),
                candidate_content_retirement: std::mem::ManuallyDrop::new(None),
                displaced_content_retirements: std::mem::ManuallyDrop::new(None),
                displaced_content_retirement_cursor: 0,
                candidate_composition: std::mem::ManuallyDrop::new(None),
                displaced_pins: std::mem::ManuallyDrop::new(None),
                retiring_child: std::mem::ManuallyDrop::new(None),
                retiring_child_cursor: 0,
                next_member_ordinal: 0,
                view_member_ordinal: 0,
                candidate_source_generation: 0,
                member_step_sequence: 0,
                expires_at_us: u64::MAX,
                closure: None,
                committed: false,
                refusal: None,
                fold_progress: (0, 0),
                state: ActiveArtifactStoreReplacementState::Initializing,
            }
        }

        /// 🔎️ The first leg's refusal as its typed fault, for a caller that must name why a stalled
        /// replacement never reached its target state.
        #[cfg(test)]
        pub(crate) fn refusal_fault(&self) -> Option<Fault> {
            self.refusal.map(ArtifactStoreReplacementRefusal::into_fault)
        }

        /// 🧭️ Records the FIRST leg that refused and moves the replacement onto its retirement path.
        /// The first one is kept because every later state transition is a consequence of it.
        fn refuse(&mut self, refusal: ArtifactStoreReplacementRefusal) {
            self.refusal.get_or_insert(refusal);
            self.state = ActiveArtifactStoreReplacementState::RetiringRejectedMembers;
        }

        /// 🧯️ Records a broken internal invariant and hands back that site's own unchanged fault, so
        /// the direct `Err` channel keeps its exact message while the archive's terminal report gains
        /// the leg that produced it.
        fn refuse_invariant(&mut self, leg: ArtifactStoreReplacementLeg, detail: &'static str) -> Fault {
            self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg, detail });
            plugin_sdk_fault(detail)
        }

        fn request_cancel(&self) {
            self.cancel.cancel_now();
            self.cancel_signal.store(true, std::sync::atomic::Ordering::Release);
        }

        fn begin_members(&mut self, expected: usize, expires_at_us: u64) -> Result<bool, Fault> {
            if self.state != ActiveArtifactStoreReplacementState::AwaitingMembers {
                return Ok(false);
            }
            if self.member_ingress.is_some() {
                return Err(plugin_sdk_fault("owned document member ingress was already initialized"));
            }
            *self.member_ingress = Some(OwnedDocumentMemberIngressRegistry::try_new(expected)?);
            self.expires_at_us = expires_at_us;
            Ok(true)
        }

        #[expect(clippy::result_large_err, reason = "Rejected admission returns the exact retained member request and identity owner unchanged.")]
        fn admit_member(&mut self, ingress: OwnedDocumentMemberIngress) -> Result<(), (Fault, OwnedDocumentMemberIngress)> {
            if self.state != ActiveArtifactStoreReplacementState::AwaitingMembers || ingress.operation() != self.operation || ingress.generation() != self.generation {
                return Err((plugin_sdk_fault("owned document member ingress does not match the active replacement authority"), ingress));
            }
            let Some(registry) = self.member_ingress.as_mut() else {
                return Err((plugin_sdk_fault("owned document member ingress registry has not been initialized"), ingress));
            };
            registry.admit(ingress)
        }

        fn seal_members(&mut self) -> Result<(), Fault> {
            if self.state != ActiveArtifactStoreReplacementState::AwaitingMembers {
                return Err(plugin_sdk_fault("owned document member ingress cannot seal outside its exact awaiting state"));
            }
            let registry = self.member_ingress.as_mut().ok_or_else(|| plugin_sdk_fault("owned document member ingress registry has not been initialized"))?;
            if let Err(fault) = registry.seal() {
                self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg: ArtifactStoreReplacementLeg::Members, detail: "an owned-member or candidate-view authority returned its own exact refusal" });
                return Err(fault);
            }
            self.state = ActiveArtifactStoreReplacementState::OpeningMembers;
            Ok(())
        }

        fn drive_member_open(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if self.active_member_open.is_some() {
                if self.active_member_ingress.as_ref().is_none_or(|ingress| !ingress.has_identity()) {
                    return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "active member open lost its exact retained ingress identity"));
                }
                let mut sequence = self.member_step_sequence;
                let fuel = maximum_items.max(maximum_bytes.min(store::ARTIFACT_ENVELOPE_DECODE_PAGE_BYTES)) as u64;
                let mut cx = semio_framework_job::StepContext::new(self.operation, self.generation, semio_framework_job::StepBudget::new(fuel, u64::MAX), self.cancel.clone(), semio_framework_job::default_now_us, &mut sequence);
                let step = store::MemberOpenOperation::step(self.active_member_open.as_mut().expect("active member open remains retained"), &mut cx);
                self.member_step_sequence = sequence;
                return match step {
                    store::MemberOpenStep::Pending(_) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                    store::MemberOpenStep::Rejected(diagnostic) => {
                        let ordinal = self.next_member_ordinal;
                        self.refuse(if self.cancel.is_cancelled_now() { ArtifactStoreReplacementRefusal::Cancelled } else { ArtifactStoreReplacementRefusal::MemberOpenRejected { ordinal, diagnostic } });
                        self.state = ActiveArtifactStoreReplacementState::ClosingRejectedMember;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    store::MemberOpenStep::Ready(member) => {
                        if !store::MemberOpenOperation::terminal_is_empty(self.active_member_open.as_ref().expect("ready member open remains retained")) {
                            *self.retiring_child = self.active_member_ingress.as_mut().and_then(OwnedDocumentMemberIngress::take_identity).map(|(_, reference, owner)| ChildMemberRetirement::new(ChildMemberEntry { reference, owner, member }));
                            return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "ready member open retained nonterminal ownership"));
                        }
                        drop(self.active_member_open.take());
                        let (ordinal, reference, owner) = self.active_member_ingress.as_mut().and_then(OwnedDocumentMemberIngress::take_identity).expect("active member identity was verified before its exact open step");
                        if ordinal != self.next_member_ordinal || member.artifact_ref().as_ref() != Some(&reference) || member.owner_ref().as_ref() != Some(&owner) {
                            *self.retiring_child = Some(ChildMemberRetirement::new(ChildMemberEntry { reference, owner, member }));
                            self.refuse(ArtifactStoreReplacementRefusal::MemberIdentityMismatch { ordinal, expected: self.next_member_ordinal });
                            return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                        }
                        let Some(candidate) = self.candidate_children.as_mut() else {
                            *self.retiring_child = Some(ChildMemberRetirement::new(ChildMemberEntry { reference, owner, member }));
                            return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "member candidate registry was lost before exact admission"));
                        };
                        let admission = match candidate.admit_identity(&owner.slot, &reference.artifact_id) {
                            Ok(admission) => admission,
                            Err(fault) => {
                                *self.retiring_child = Some(ChildMemberRetirement::new(ChildMemberEntry { reference, owner, member }));
                                self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg: ArtifactStoreReplacementLeg::Members, detail: "an owned-member or candidate-view authority returned its own exact refusal" });
                                return Err(fault);
                            }
                        };
                        let Some(candidate_source_generation) = self.candidate_source_generation.checked_add(1) else {
                            let cancelled = candidate.cancel_admission(&admission);
                            debug_assert!(cancelled, "candidate admission remains exclusive until insertion");
                            *self.retiring_child = Some(ChildMemberRetirement::new(ChildMemberEntry { reference, owner, member }));
                            return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "owned document candidate generation exhausted"));
                        };
                        candidate.insert_admitted(admission, reference, owner, member);
                        let ingress = self.active_member_ingress.take().expect("ready member ingress remains retained");
                        if !ingress.terminal_is_empty() {
                            return Err(plugin_sdk_fault("ready member ingress retained ownership after exact handoff"));
                        }
                        drop(ingress);
                        self.next_member_ordinal += 1;
                        self.candidate_source_generation = candidate_source_generation;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                };
            }
            let Some(registry) = self.member_ingress.as_mut() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "opening member set lost its exact ingress registry"));
            };
            if self.next_member_ordinal == registry.expected {
                if !registry.sealed || !registry.terminal_is_empty() {
                    return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "opened member set did not consume every sealed ordinal"));
                }
                let registry = self.member_ingress.take().expect("terminal member ingress registry remains retained");
                drop(registry);
                self.closure = Some(store::OwnedDocumentClosure::new(self.operation, self.generation, self.candidate_source_generation, self.expires_at_us));
                self.state = ActiveArtifactStoreReplacementState::ValidatingClosure;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let Some(ingress) = registry.take(self.next_member_ordinal) else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "sealed member set lost an exact ordinal before open"));
            };
            *self.active_member_ingress = Some(ingress);
            if self.active_member_ingress.as_ref().is_none_or(|ingress| !ingress.has_request()) {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Members, "member ingress lost its exact retained open request"));
            }
            let request = self.active_member_ingress.as_mut().and_then(OwnedDocumentMemberIngress::take_request).expect("active member request was verified before exact factory handoff");
            match M::begin_open(request) {
                Ok(open) => {
                    *self.active_member_open = Some(open);
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Err(rejected) => {
                    let ordinal = self.next_member_ordinal;
                    self.active_member_ingress.as_mut().expect("rejected member ingress remains retained").return_request(rejected.request);
                    self.refuse(ArtifactStoreReplacementRefusal::MemberFactoryRefused { ordinal });
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
            }
        }

        /// 🌱️ The hydrated candidate parent while its member roster is still open — the only window in
        /// which a derivable child may still be minted onto the roster (`complete_document_archive_genesis`).
        fn candidate_awaiting_members(&self) -> Option<&ArtifactStore<P, Mutation>> {
            (self.state == ActiveArtifactStoreReplacementState::AwaitingMembers).then(|| self.retained_store.as_deref()).flatten()
        }

        fn drive_closure(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 || maximum_bytes < store::MEMBER_OPEN_IDENTITY_BYTES {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let Some(candidate) = self.retained_store.as_ref() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Closure, "closure validation lost its retained parent candidate"));
            };
            let Some(dialect) = candidate.envelope().dialect.clone() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Closure, "closure validation requires the candidate parent's exact dialect"));
            };
            let root_reference = ArtifactRef { artifact_id: candidate.envelope().id.clone(), dialect };
            let Some(children) = self.candidate_children.as_ref() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Closure, "closure validation lost its retained member registry"));
            };
            let source = DocumentClosureSourceView::new(self.candidate_source_generation, &root_reference, candidate.snapshot_ref(), children);
            let mut sequence = self.member_step_sequence;
            let mut cx = semio_framework_job::StepContext::new(self.operation, self.generation, semio_framework_job::StepBudget::new(maximum_items as u64, u64::MAX), self.cancel.clone(), semio_framework_job::default_now_us, &mut sequence);
            let Some(closure) = self.closure.as_mut() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::Closure, "closure validation lost its fixed cursor"));
            };
            let step = closure.step(&source, &mut cx);
            let children_len = children.len();
            self.member_step_sequence = sequence;
            match step {
                store::OwnedDocumentClosureStep::Pending(_) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                store::OwnedDocumentClosureStep::Complete { members } if members == children_len => {
                    self.closure = None;
                    self.state = ActiveArtifactStoreReplacementState::PreparingCandidateViews;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                store::OwnedDocumentClosureStep::Complete { members } => {
                    self.closure = None;
                    self.refuse(ArtifactStoreReplacementRefusal::ClosureMemberCount { members, children: children_len });
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                store::OwnedDocumentClosureStep::Rejected(diagnostic) => {
                    self.closure = None;
                    self.refuse(ArtifactStoreReplacementRefusal::ClosureRejected { diagnostic });
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
            }
        }

        fn drive_candidate_views(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            if maximum_items == 0 || maximum_bytes < OWNED_DOCUMENT_MEMBER_PREPARATION_BYTES {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            let Some(children) = self.candidate_children.as_ref() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::CandidateViews, "candidate view preparation lost its exact member registry"));
            };
            if self.candidate_source_generation != children.len() as u64 {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::CandidateViews, "candidate member generation changed after closure validation"));
            }
            if self.candidate_composition.is_none() {
                let composition = match CompositionCoordinator::try_for_owned_closure(children.len()) {
                    Ok(composition) => composition,
                    Err(error) => {
                        self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg: ArtifactStoreReplacementLeg::CandidateViews, detail: "an app-owned candidate-view owner refused its exact step" });
                        return Err(plugin_sdk_fault(error));
                    }
                };
                *self.candidate_composition = Some(composition);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if self.view_member_ordinal == children.len() {
                self.state = ActiveArtifactStoreReplacementState::CandidateReady;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            let Some(entry) = children.entry_by_ordinal(self.view_member_ordinal) else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::CandidateViews, "candidate view preparation lost its exact member ordinal"));
            };
            if entry.member.artifact_ref().as_ref() != Some(&entry.reference) || entry.member.owner_ref().as_ref() != Some(&entry.owner) {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::CandidateViews, "candidate member identity changed after closure validation"));
            }
            let Some(content) = self.candidate_content.as_ref() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::CandidateViews, "candidate view preparation lost its immutable content root"));
            };
            let index = match content.admit_member(&entry.owner.slot, &entry.reference.artifact_id) {
                Ok(index) => index,
                Err(fault) => {
                    self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg: ArtifactStoreReplacementLeg::CandidateViews, detail: "an owned-member or candidate-view authority returned its own exact refusal" });
                    return Err(fault);
                }
            };
            let Some(composition) = self.candidate_composition.as_mut() else {
                return Err(self.refuse_invariant(ArtifactStoreReplacementLeg::CandidateViews, "candidate view preparation lost its coordinator"));
            };
            if let Err(error) = composition.insert_validated_owned(&entry.owner.parent.artifact_id, &entry.owner.slot, &entry.reference.artifact_id) {
                self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg: ArtifactStoreReplacementLeg::CandidateViews, detail: "an app-owned candidate-view owner refused its exact step" });
                return Err(plugin_sdk_fault(error));
            }
            let revision = entry.member.content_revision_now();
            let snapshot = match entry.member.snapshot_read_erased_now() {
                Ok(snapshot) => snapshot,
                Err(error) => {
                    self.refuse(ArtifactStoreReplacementRefusal::Invariant { leg: ArtifactStoreReplacementLeg::CandidateViews, detail: "an app-owned candidate-view owner refused its exact step" });
                    return Err(plugin_sdk_fault(error));
                }
            };
            let prior = self.candidate_content.take().expect("candidate content owner was verified before snapshot-read issuance");
            *self.candidate_content = Some(prior.insert_entry_admitted(index, ChildContentEntry { slot: entry.owner.slot.clone(), child_id: entry.reference.artifact_id.clone(), dialect: entry.reference.dialect.clone(), revision, snapshot }));
            self.view_member_ordinal += 1;
            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
        }

        fn drive_rejected_members(&mut self, current_content: &ChildContentView, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            self.closure = None;
            if let Some(open) = self.active_member_open.as_mut() {
                return match store::MemberOpenOperation::close_step(open, maximum_items.min(1), maximum_bytes).map_err(|error| plugin_sdk_fault(error.to_string()))? {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Pending { .. } => Err(plugin_sdk_fault("rejected member open exceeded its exact close grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "rejected member open is blocked" }),
                    store::SnapshotRetirementStep::Complete if store::MemberOpenOperation::terminal_is_empty(open) => {
                        drop(self.active_member_open.take());
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    store::SnapshotRetirementStep::Complete => Err(plugin_sdk_fault("rejected member open returned false terminal")),
                };
            }
            if let Some(ingress) = self.active_member_ingress.as_mut() {
                let step = ingress.close_step(maximum_items.min(1), maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    if !ingress.terminal_is_empty() {
                        return Err(plugin_sdk_fault("rejected active member ingress returned false terminal"));
                    }
                    drop(self.active_member_ingress.take());
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if let Some(registry) = self.member_ingress.as_mut() {
                let step = registry.close_step(maximum_items.min(1), maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    if !registry.terminal_is_empty() {
                        return Err(plugin_sdk_fault("rejected member ingress registry returned false terminal"));
                    }
                    drop(self.member_ingress.take());
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if let Some(retirements) = self.displaced_content_retirements.as_mut() {
                let Some((index, generation)) = retirements.next_id_from(self.displaced_content_retirement_cursor) else {
                    let retirements = self.displaced_content_retirements.take().expect("empty displaced content retirement registry remains retained");
                    drop(retirements);
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                };
                let children = self.candidate_children.as_mut().ok_or_else(|| plugin_sdk_fault("displaced content retirement lost its exact member registry"))?;
                let current = self.candidate_content.as_ref().ok_or_else(|| plugin_sdk_fault("displaced content retirement lost its exact current root"))?;
                let owners = retirements.sibling_content_owners(generation);
                let step = retirements.get_mut(generation).ok_or_else(|| plugin_sdk_fault("displaced content retirement changed before one bounded step"))?.close_step(children, None, current, &owners, maximum_items.min(1), maximum_bytes)?;
                if step != PluginCloseStep::Complete {
                    self.displaced_content_retirement_cursor = index;
                    return Ok(step);
                }
                if !retirements.get(generation).is_some_and(ChildContentRetirement::terminal_is_empty) {
                    return Err(plugin_sdk_fault("displaced content retirement returned false terminal"));
                }
                let retirement = retirements.remove(generation).expect("terminal displaced content retirement remains retained");
                drop(retirement);
                self.displaced_content_retirement_cursor = (index + 1) % ARTIFACT_LIVE_OUTPUT_SLOTS;
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(retirement) = self.candidate_content_retirement.as_mut() {
                let children = self.candidate_children.as_mut().ok_or_else(|| plugin_sdk_fault("candidate content retirement lost its exact member registry"))?;
                let step = retirement.close_step(children, None, current_content, &ChildContentOwners::none(), maximum_items.min(1), maximum_bytes)?;
                if step == PluginCloseStep::Complete {
                    if !retirement.terminal_is_empty() {
                        return Err(plugin_sdk_fault("candidate content retirement returned false terminal"));
                    }
                    drop(self.candidate_content_retirement.take());
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if let Some(content) = self.candidate_content.take() {
                if content.is_empty() {
                    drop(content);
                } else {
                    *self.candidate_content_retirement = Some(ChildContentRetirement::new(content, true));
                }
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            if let Some(composition) = self.candidate_composition.as_mut() {
                return match composition.close_step(maximum_items.min(1), maximum_bytes) {
                    store::SnapshotRetirementStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    store::SnapshotRetirementStep::Pending { .. } => Err(plugin_sdk_fault("candidate composition retirement exceeded its exact close grant")),
                    store::SnapshotRetirementStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "candidate composition retirement is blocked" }),
                    store::SnapshotRetirementStep::Complete if composition.terminal_is_empty() => {
                        drop(self.candidate_composition.take());
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    store::SnapshotRetirementStep::Complete => Err(plugin_sdk_fault("candidate composition retirement returned false terminal")),
                };
            }
            if let Some(pins) = self.displaced_pins.as_mut() {
                let step = pins.close_step(maximum_items.min(1), maximum_bytes);
                if step == PluginCloseStep::Complete {
                    if !pins.terminal_is_empty() {
                        return Err(plugin_sdk_fault("displaced composition pins returned false terminal"));
                    }
                    drop(self.displaced_pins.take());
                    return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                }
                return Ok(step);
            }
            if let Some(retirement) = self.retiring_child.as_mut() {
                let step = retirement.close_step(maximum_items.min(1), maximum_bytes)?;
                if retirement.terminal_is_empty() {
                    drop(self.retiring_child.take());
                }
                return Ok(step);
            }
            if let Some(children) = self.candidate_children.as_mut() {
                while self.retiring_child_cursor < CHILD_CONTENT_SLOTS {
                    let index = self.retiring_child_cursor;
                    self.retiring_child_cursor += 1;
                    if let Some(entry) = children.take_at(index) {
                        *self.retiring_child = Some(ChildMemberRetirement::new(entry));
                        return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
                    }
                }
                if !children.is_empty() {
                    return Err(plugin_sdk_fault("rejected candidate member registry retained an unreachable owner"));
                }
                let children = self.candidate_children.take().expect("empty candidate member registry remains retained");
                drop(children);
                return Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 });
            }
            self.state = if self.retained_store.is_some() {
                if self.committed {
                    ActiveArtifactStoreReplacementState::RetiringCommittedStore
                } else {
                    ActiveArtifactStoreReplacementState::RetiringRejectedCandidate
                }
            } else {
                ActiveArtifactStoreReplacementState::Complete
            };
            Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
        }

        fn drive_initializer(&mut self, pool: &semio_framework_async::WorkerPool) -> Result<PluginCloseStep, Fault> {
            if self.state != ActiveArtifactStoreReplacementState::Initializing {
                return Ok(PluginCloseStep::Pending { released_items: 0, released_bytes: 0 });
            }
            if let Some(rejected) = self.session_rejected.as_mut() {
                return match rejected.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {
                    semio_framework_job::InteractiveJobCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::InteractiveJobCloseStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "store initializer admission rejection is temporarily blocked" }),
                    semio_framework_job::InteractiveJobCloseStep::Complete if rejected.terminal_is_empty() => {
                        drop(self.session_rejected.take());
                        self.refuse(ArtifactStoreReplacementRefusal::InitializerAdmissionRejected);
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::InteractiveJobCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-rejected-false-terminal"), "store initializer rejection reported Complete without terminal-empty authority"))
                    }
                };
            }
            if let Some(outcome) = self.retained_outcome.as_mut() {
                return match outcome.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {
                    semio_framework_job::JobPayloadCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::JobPayloadCloseStep::Complete if outcome.terminal_is_empty() => {
                        drop(self.retained_outcome.take());
                        if self.terminal_target.is_none() {
                            self.session
                                .as_mut()
                                .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-session-missing"), "store initializer lost its retained session before resume"))?
                                .resume()
                                .map_err(|_| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-resume"), "store initializer lost its exact resume authority"))?;
                        }
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::JobPayloadCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-outcome-false-terminal"), "store initializer outcome reported Complete without terminal-empty payload"))
                    }
                };
            }
            if let Some(target) = self.terminal_target {
                let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-session-missing"), "terminal store initializer lost its retained session"))?;
                session.begin_close();
                return match session.close_step(1, semio_framework_job::JOB_PAYLOAD_PAGE_BYTES) {
                    semio_framework_job::WorkerJobCloseStep::Pending { released_items, released_bytes } => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                    semio_framework_job::WorkerJobCloseStep::Blocked => Ok(PluginCloseStep::Blocked { reason: "terminal store initializer close is temporarily blocked" }),
                    semio_framework_job::WorkerJobCloseStep::Complete if session.terminal_is_empty() => {
                        drop(self.session.take());
                        self.terminal_target = None;
                        self.state = target;
                        Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                    }
                    semio_framework_job::WorkerJobCloseStep::Complete => {
                        Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-session-false-terminal"), "store initializer session reported Complete without terminal-empty authority"))
                    }
                };
            }
            let session = self.session.as_mut().ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-session-missing"), "store initializer lost its retained session before terminal recovery"))?;
            match session.pump_one_for_interactive_turn(pool, semio_framework_async::Lane::Interactive) {
                Ok(semio_framework_job::WorkerJobPoll::Outcome | semio_framework_job::WorkerJobPoll::Terminal) => {
                    let (terminal_kind, initializer_code) = session
                        .checked_out_outcome()
                        .map(|outcome| match outcome {
                            semio_framework_job::StepOutcome::Complete(_) => (1, ArtifactStoreRefusalCode::EMPTY),
                            semio_framework_job::StepOutcome::Cancelled => (2, ArtifactStoreRefusalCode::from_page(b"initializer-cancelled")),
                            semio_framework_job::StepOutcome::Fault(fault) => (2, ArtifactStoreRefusalCode::from_page(fault.detail.page(0).unwrap_or(b"initializer-faulted-without-detail"))),
                            _ => (0, ArtifactStoreRefusalCode::EMPTY),
                        })
                        .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-outcome-missing"), "store initializer checkout lost its exact outcome"))?;
                    if let Some(progress) = session.checked_out_job_mut().map(|job| job.progress()).filter(|(_, total)| *total > 0) {
                        self.fold_progress = progress;
                    }
                    if terminal_kind == 1 {
                        let candidate = session
                            .checked_out_job_mut()
                            .and_then(ArtifactStoreInitializationJob::take_candidate)
                            .ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-candidate-missing"), "completed store initializer lost its exact candidate"))?;
                        *self.retained_store = Some(candidate);
                        self.terminal_target = Some(ActiveArtifactStoreReplacementState::AwaitingMembers);
                    } else if terminal_kind == 2 {
                        let released = session.checked_out_job_mut().is_some_and(ArtifactStoreInitializationJob::release_terminal_failure);
                        if !released {
                            return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.initializer-failure-retirement"), "failed store initializer did not reach terminal-empty authority"));
                        }
                        self.refusal.get_or_insert(ArtifactStoreReplacementRefusal::InitializerFailed(initializer_code));
                        self.terminal_target = Some(ActiveArtifactStoreReplacementState::RetiringRejectedMembers);
                    }
                    *self.retained_outcome = session.take_checked_out_outcome();
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                Ok(semio_framework_job::WorkerJobPoll::Submitted | semio_framework_job::WorkerJobPoll::Idle) => Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }),
                Ok(_) => Ok(PluginCloseStep::Blocked { reason: "store initializer awaits its mounted wake" }),
                Err(_) => Ok(PluginCloseStep::Blocked { reason: "store initializer worker lane is saturated or contended" }),
            }
        }

        fn drive_retained_store(&mut self, maximum_items: usize, maximum_bytes: usize) -> Result<PluginCloseStep, Fault> {
            let Some(store) = self.retained_store.as_mut() else {
                self.state = ActiveArtifactStoreReplacementState::Complete;
                return Ok(PluginCloseStep::Complete);
            };
            let Some(disposer) = self.retained_disposer.as_mut() else {
                return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-disposer-missing"), "retained replacement store lost its exact disposer"));
            };
            match disposer.close_step(store, maximum_items.min(1), maximum_bytes)? {
                PluginCloseStep::Pending { released_items, released_bytes } if released_items <= 1 && released_bytes <= maximum_bytes => Ok(PluginCloseStep::Pending { released_items, released_bytes }),
                PluginCloseStep::Pending { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-close-over-budget"), "retained replacement store exceeded its exact close grant")),
                PluginCloseStep::AwaitingInput { .. } => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-close-awaiting-input"), "retained replacement store disposer requested application input during close")),
                step @ PluginCloseStep::Blocked { .. } => Ok(step),
                PluginCloseStep::Complete if disposer.terminal_is_empty(store) => {
                    drop(self.retained_disposer.take());
                    let store = self.retained_store.take().expect("terminal replacement store remains retained");
                    drop(store);
                    self.state = ActiveArtifactStoreReplacementState::Complete;
                    Ok(PluginCloseStep::Pending { released_items: 1, released_bytes: 0 })
                }
                PluginCloseStep::Complete => Err(Fault::new(FaultOrigin::Framework, FaultCode::new("artifact-store.replacement-false-terminal"), "retained replacement store disposer reported Complete without terminal-empty ownership")),
            }
        }

        fn terminal_is_empty(&self) -> bool {
            self.state == ActiveArtifactStoreReplacementState::Complete
                && self.session.is_none()
                && self.session_rejected.is_none()
                && self.retained_outcome.is_none()
                && self.retained_store.is_none()
                && self.retained_disposer.is_none()
                && self.member_ingress.is_none()
                && self.active_member_ingress.is_none()
                && self.active_member_open.is_none()
                && self.candidate_children.is_none()
                && self.candidate_content.is_none()
                && self.candidate_content_retirement.is_none()
                && self.displaced_content_retirements.is_none()
                && self.candidate_composition.is_none()
                && self.displaced_pins.is_none()
                && self.retiring_child.is_none()
        }
    }

    impl<P, Mutation, M> Drop for ActiveArtifactStoreReplacement<P, Mutation, M>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + ArtifactPack + semio_framework_schema_composition::ArtifactCompositionFields + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
        M: SpaceMember + MemberFactory,
    {
        fn drop(&mut self) {
            assert!(
                std::thread::panicking()
                    || self.state == ActiveArtifactStoreReplacementState::Complete
                        && self.session.is_none()
                        && self.session_rejected.is_none()
                        && self.retained_outcome.is_none()
                        && self.retained_store.is_none()
                        && self.retained_disposer.is_none()
                        && self.member_ingress.is_none()
                        && self.active_member_ingress.is_none()
                        && self.active_member_open.is_none()
                        && self.candidate_children.is_none()
                        && self.candidate_content.is_none()
                        && self.candidate_content_retirement.is_none()
                        && self.displaced_content_retirements.is_none()
                        && self.candidate_composition.is_none()
                        && self.displaced_pins.is_none()
                        && self.retiring_child.is_none(),
                "artifact store replacement reached Drop before initializer/candidate/displaced-store ownership was terminal empty"
            );
        }
    }

    struct ArtifactStoreReplacementAdmissionTarget<'a, A: ArtifactApp, M: SpaceMember + MemberFactory> {
        jobs: &'a mut ArtifactFixedRegistry<ActiveArtifactStoreReplacement<A::Snapshot, A::Mutation, M>>,
        operation: semio_framework_job::OperationId,
        generation: semio_framework_job::Generation,
        child_content_generation: u64,
        marker: std::marker::PhantomData<fn() -> A>,
    }

    impl<A: ArtifactApp, M: SpaceMember + MemberFactory> store::ArtifactEnvelopeCompletedRecordTarget<A::Snapshot, A::Mutation> for ArtifactStoreReplacementAdmissionTarget<'_, A, M> {
        fn try_adopt_completed(&mut self, mut envelope: ArtifactEnvelope<A::Snapshot, A::Mutation>) -> Result<(), ArtifactEnvelope<A::Snapshot, A::Mutation>> {
            if envelope.dialect.is_none() {
                envelope.dialect = Some(A::DIALECT.into());
            }
            if envelope.schema != A::DOCUMENT_SCHEMA || envelope.dialect != Some(A::DIALECT.into()) || !self.jobs.can_insert(self.operation.0) {
                return Err(envelope);
            }
            let job = A::build_document_store_initialization_job(envelope, self.operation, self.generation)?;
            self.jobs.insert_admitted(self.operation.0, ActiveArtifactStoreReplacement::new(self.operation, self.generation, self.child_content_generation, job));
            Ok(())
        }
    }

    /// 🚫️async: `M` (`SpaceMember + MemberFactory`, default `store::NoMembers`) types this app's
    /// composed CHILDREN only — the STORE-side dedyn shape (see `📓️terra-store-dedyn-report.md`),
    /// threaded through `children`/`register_child`/`open_child`/`absorb_created_children` below.
    /// It deliberately does NOT reach `self.store` (the PARENT's own `ArtifactStore<A::Snapshot,
    /// A::Mutation>`, a different, per-`A` concrete type) or `ChildContentView` (function-generic
    /// over `M`, not struct-generic — see its own doc comment): both of those are fixed by
    /// constraints outside this file's reach, documented in
    /// `📓️terra-dedyn-fw-os-spacemember-report.md`.
    pub(crate) struct ArtifactCacheRetirement<A: ArtifactApp> {
        pub(crate) snapshot: Option<std::sync::Arc<A::Snapshot>>,
        pub(crate) config: Option<std::sync::Arc<A::Config>>,
        pub(crate) history: Option<std::sync::Arc<HistoryView>>,
    }

    impl<A: ArtifactApp> ArtifactCacheRetirement<A> {
        pub(crate) fn close_step(&mut self, maximum_items: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if self.history.is_some() {
                drop(self.history.take());
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.config.is_some() {
                drop(self.config.take());
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if self.snapshot.is_some() {
                drop(self.snapshot.take());
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            PluginCloseStep::Complete
        }

        pub(crate) fn terminal_is_empty(&self) -> bool {
            self.snapshot.is_none() && self.config.is_none() && self.history.is_none()
        }
    }

    /// 🗂️ Generation-keyed immutable document, configuration, and history projections.
    type AppProjectionCache<A> = ((u64, u64, u64, HistoryCommandFilter), std::sync::Arc<<A as ArtifactApp>::Snapshot>, std::sync::Arc<<A as ArtifactApp>::Config>, std::sync::Arc<HistoryView>);

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ActiveDocumentArchiveLoadState {
        Pending,
        Running,
        Ready,
        Cancelled,
        Fault,
    }

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    enum ActiveDocumentArchiveLoadPhase {
        DecodeParent,
        RetireParentHistoryAuxiliary,
        HydrateParent,
        AwaitingMembers,
        BeginMember,
        FillMember,
        RetireMemberSource,
        AdmitMember,
        SealMembers,
        AwaitReplacement,
        Terminal,
    }

    struct PendingDocumentArchiveMember {
        entry: Option<protocol::OwnedDocumentMemberPackEntry>,
        pages: Option<store::OwnedSchemaDecodePages>,
        copied: usize,
        identity_field: u8,
    }

    impl PendingDocumentArchiveMember {
        fn empty_ingress() -> OwnedDocumentMemberIngress {
            OwnedDocumentMemberIngress { identity: std::mem::ManuallyDrop::new(None), request: std::mem::ManuallyDrop::new(None), identity_field: 0 }
        }

        fn new(entry: protocol::OwnedDocumentMemberPackEntry) -> Result<Self, (Fault, protocol::OwnedDocumentMemberPackEntry)> {
            let page_count = entry.envelope_pack.len().div_ceil(store::OWNED_SCHEMA_DECODE_PAGE_BYTES);
            let pages = match store::OwnedSchemaDecodePages::try_with_credits(store::OwnedSchemaDecodeCredits { maximum_pages: page_count, maximum_bytes: entry.envelope_pack.len() }) {
                Ok(pages) => pages,
                Err(fault) => return Err((plugin_sdk_fault(format!("document archive member page authority was rejected: {fault:?}")), entry)),
            };
            Ok(Self { entry: Some(entry), pages: Some(pages), copied: 0, identity_field: 0 })
        }

        fn fill_one_page(&mut self, maximum_bytes: usize) -> Result<bool, Fault> {
            let entry = self.entry.as_ref().ok_or_else(|| plugin_sdk_fault("document archive member source owner is absent"))?;
            if self.copied == entry.envelope_pack.len() {
                return Ok(true);
            }
            let end = self.copied.saturating_add(store::OWNED_SCHEMA_DECODE_PAGE_BYTES).min(entry.envelope_pack.len());
            let length = end - self.copied;
            if length > maximum_bytes {
                return Ok(false);
            }
            let page = store::OwnedSchemaDecodePage::try_from_slice(&entry.envelope_pack[self.copied..end]).map_err(|_| plugin_sdk_fault("document archive member page exceeded its fixed extent"))?;
            self.pages.as_mut().ok_or_else(|| plugin_sdk_fault("document archive member page owner is absent"))?.admit_page(page).map_err(|_| plugin_sdk_fault("document archive member page was rejected by its exact authority"))?;
            self.copied = end;
            Ok(self.copied == entry.envelope_pack.len())
        }

        fn retire_source_step(&mut self, maximum_bytes: usize) -> PluginCloseStep {
            let Some(entry) = self.entry.as_mut() else { return PluginCloseStep::Complete };
            if entry.envelope_pack.is_empty() {
                return PluginCloseStep::Complete;
            }
            let released_bytes = entry.envelope_pack.len().min(maximum_bytes);
            if released_bytes == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            entry.envelope_pack.truncate(entry.envelope_pack.len() - released_bytes);
            PluginCloseStep::Pending { released_items: 0, released_bytes }
        }

        fn take_ingress(&mut self, handle: ArtifactEnvelopeDecodeOperationHandle) -> Result<OwnedDocumentMemberIngress, (Fault, OwnedDocumentMemberIngress)> {
            let mut entry = self.entry.take().ok_or_else(|| (plugin_sdk_fault("document archive member identity owner is absent"), Self::empty_ingress()))?;
            if !entry.envelope_pack.is_empty() {
                self.entry = Some(entry);
                return Err((plugin_sdk_fault("document archive member source bytes remain live before identity transfer"), Self::empty_ingress()));
            }
            let mut pages = self.pages.take().ok_or_else(|| (plugin_sdk_fault("document archive member page owner is absent"), Self::empty_ingress()))?;
            if let Err(fault) = pages.seal() {
                self.entry = Some(entry);
                self.pages = Some(pages);
                return Err((plugin_sdk_fault(format!("document archive member pages could not seal: {fault:?}")), Self::empty_ingress()));
            }
            let reference = ArtifactRef {
                artifact_id: std::mem::take(&mut entry.reference.artifact_id),
                dialect: ArtifactDialect { artifact_kind: std::mem::take(&mut entry.reference.artifact_kind), standard: std::mem::take(&mut entry.reference.standard), subset: std::mem::take(&mut entry.reference.subset) },
            };
            let owner = store::OwnerRef {
                parent: ArtifactRef {
                    artifact_id: std::mem::take(&mut entry.owner.parent.artifact_id),
                    dialect: ArtifactDialect { artifact_kind: std::mem::take(&mut entry.owner.parent.artifact_kind), standard: std::mem::take(&mut entry.owner.parent.standard), subset: std::mem::take(&mut entry.owner.parent.subset) },
                },
                slot: std::mem::take(&mut entry.owner.slot),
                child_id: std::mem::take(&mut entry.owner.child_id),
            };
            let ordinal = entry.ordinal as usize;
            drop(entry);
            let request = match store::MemberOpenRequest::new(handle.operation, handle.generation, u64::MAX, reference.clone(), Some(owner.clone()), pages).admit(1) {
                Ok(request) => request,
                Err(rejected) => {
                    let ingress = OwnedDocumentMemberIngress { identity: std::mem::ManuallyDrop::new(Some((ordinal, reference, owner))), request: std::mem::ManuallyDrop::new(Some(rejected.request)), identity_field: 0 };
                    return Err((plugin_sdk_fault(format!("document archive member request was rejected: {:?}", rejected.diagnostic)), ingress));
                }
            };
            OwnedDocumentMemberIngress::try_new(ordinal, reference, owner, request)
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(pages) = self.pages.as_mut() {
                if let Some(page) = pages.close_take_page() {
                    let released_bytes = page.len();
                    if released_bytes > maximum_bytes {
                        pages.admit_preflighted_page(page);
                        return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    let _ = page;
                    return PluginCloseStep::Pending { released_items: 1, released_bytes };
                }
                self.pages = None;
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            let Some(entry) = self.entry.as_mut() else { return PluginCloseStep::Complete };
            if !entry.envelope_pack.is_empty() {
                let released_bytes = entry.envelope_pack.len().min(maximum_bytes);
                if released_bytes == 0 {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                entry.envelope_pack.truncate(entry.envelope_pack.len() - released_bytes);
                return PluginCloseStep::Pending { released_items: 0, released_bytes };
            }
            while self.identity_field < 10 && document_archive_member_identity_mut(entry, self.identity_field).is_some_and(|field| field.is_empty()) {
                self.identity_field += 1;
            }
            if let Some(field) = document_archive_member_identity_mut(entry, self.identity_field) {
                let bytes = field.chars().next_back().map_or(0, char::len_utf8);
                if bytes > maximum_bytes {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                field.pop();
                return PluginCloseStep::Pending { released_items: 0, released_bytes: bytes };
            }
            drop(self.entry.take());
            PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
        }

        fn terminal_is_empty(&self) -> bool {
            self.entry.is_none() && self.pages.is_none()
        }
    }

    impl Drop for PendingDocumentArchiveMember {
        fn drop(&mut self) {
            assert!(std::thread::panicking() || self.terminal_is_empty(), "recursive document archive member reached Drop before its source and page owners were terminal empty");
        }
    }

    fn document_archive_member_identity_mut(entry: &mut protocol::OwnedDocumentMemberPackEntry, field: u8) -> Option<&mut String> {
        match field {
            0 => Some(&mut entry.reference.artifact_id),
            1 => Some(&mut entry.reference.artifact_kind),
            2 => Some(&mut entry.reference.standard),
            3 => Some(&mut entry.reference.subset),
            4 => Some(&mut entry.owner.parent.artifact_id),
            5 => Some(&mut entry.owner.parent.artifact_kind),
            6 => Some(&mut entry.owner.parent.standard),
            7 => Some(&mut entry.owner.parent.subset),
            8 => Some(&mut entry.owner.slot),
            9 => Some(&mut entry.owner.child_id),
            _ => None,
        }
    }

    struct ActiveDocumentArchiveLoad<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P>,
    {
        operation: u64,
        archive: Option<Box<protocol::DocumentArchivePack>>,
        history: Option<protocol::RetainedHistoryDecode>,
        decoded_history: Option<protocol::HistoryLog>,
        member: Option<PendingDocumentArchiveMember>,
        rejected_ingress: Option<OwnedDocumentMemberIngress>,
        retained: Option<Box<dyn store::ErasedSnapshotRetirement>>,
        hydration: Option<store::RetainedPersistedDocumentHydration<P, Mutation>>,
        hydration_sequence: u64,
        replacement: Option<ArtifactEnvelopeDecodeOperationHandle>,
        genesis_complete: bool,
        phase: ActiveDocumentArchiveLoadPhase,
        terminal_target: Option<ActiveDocumentArchiveLoadState>,
        close_identity_field: u8,
        state: ActiveDocumentArchiveLoadState,
        completed: u64,
        total: u64,
        fold: (u64, u64),
        fault: Vec<u8>,
    }

    impl<P, Mutation> ActiveDocumentArchiveLoad<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue + store::ArtifactPack + Send + Sync + 'static,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P> + OpBinary + OpText + Send + 'static,
    {
        fn new(operation: u64, archive: protocol::DocumentArchivePack, history: protocol::RetainedHistoryDecode) -> Self {
            let total = archive.members.len() as u64 + 1;
            Self {
                operation,
                archive: Some(Box::new(archive)),
                history: Some(history),
                decoded_history: None,
                member: None,
                rejected_ingress: None,
                retained: None,
                hydration: None,
                hydration_sequence: 0,
                replacement: None,
                genesis_complete: false,
                phase: ActiveDocumentArchiveLoadPhase::DecodeParent,
                terminal_target: None,
                close_identity_field: 0,
                state: ActiveDocumentArchiveLoadState::Pending,
                completed: 0,
                total,
                fold: (0, 0),
                fault: Vec::new(),
            }
        }

        fn status(&self) -> protocol::DocumentArchiveLoadStatus {
            let state = match self.state {
                ActiveDocumentArchiveLoadState::Pending => protocol::DocumentArchiveLoadState::Pending,
                ActiveDocumentArchiveLoadState::Running => protocol::DocumentArchiveLoadState::Running,
                ActiveDocumentArchiveLoadState::Ready => protocol::DocumentArchiveLoadState::Ready,
                ActiveDocumentArchiveLoadState::Cancelled => protocol::DocumentArchiveLoadState::Cancelled,
                ActiveDocumentArchiveLoadState::Fault => protocol::DocumentArchiveLoadState::Fault,
            };
            protocol::DocumentArchiveLoadStatus { operation: self.operation, state, completed: self.completed.saturating_add(self.fold.0), total: self.total.saturating_add(self.fold.1), fault: self.fault.clone() }
        }

        fn terminal(&self) -> bool {
            matches!(self.state, ActiveDocumentArchiveLoadState::Ready | ActiveDocumentArchiveLoadState::Cancelled | ActiveDocumentArchiveLoadState::Fault)
        }

        fn terminal_is_empty(&self) -> bool {
            self.archive.is_none() && self.history.is_none() && self.decoded_history.is_none() && self.member.is_none() && self.rejected_ingress.is_none() && self.retained.is_none() && self.hydration.is_none() && self.replacement.is_none()
        }

        fn request_terminal(&mut self, target: ActiveDocumentArchiveLoadState) {
            if self.terminal_target.is_none() {
                self.terminal_target = Some(target);
            }
        }

        fn request_fault(&mut self, fault: &Fault) {
            if self.terminal_target.is_none() {
                self.fault = semio_framework_diagnostic::encode_fault_bytes(fault);
                self.terminal_target = Some(ActiveDocumentArchiveLoadState::Fault);
            }
        }

        fn close_step(&mut self, maximum_items: usize, maximum_bytes: usize) -> PluginCloseStep {
            if maximum_items == 0 {
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            if let Some(retained) = self.retained.as_mut() {
                return match retained.close_step(maximum_items, maximum_bytes) {
                    Ok(store::SnapshotRetirementStep::Pending { released_items, released_bytes }) => PluginCloseStep::Pending { released_items, released_bytes },
                    Ok(store::SnapshotRetirementStep::Blocked) => PluginCloseStep::Blocked { reason: "recursive archive partial decoded owner retirement is blocked" },
                    Ok(store::SnapshotRetirementStep::Complete) if retained.terminal_is_empty() => {
                        self.retained = None;
                        PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
                    }
                    _ => PluginCloseStep::Blocked { reason: "recursive archive partial decoded owner returned an invalid retirement step" },
                };
            }
            if let Some(hydration) = self.hydration.as_mut() {
                return match store::ErasedSnapshotRetirement::close_step(hydration, maximum_items.min(1), maximum_bytes) {
                    Ok(store::SnapshotRetirementStep::Complete) if store::ErasedSnapshotRetirement::terminal_is_empty(hydration) => {
                        self.hydration = None;
                        PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
                    }
                    Ok(store::SnapshotRetirementStep::Complete) => PluginCloseStep::Blocked { reason: "recursive archive parent hydration returned false terminal" },
                    Ok(store::SnapshotRetirementStep::Pending { released_items, released_bytes }) => PluginCloseStep::Pending { released_items, released_bytes },
                    Ok(store::SnapshotRetirementStep::Blocked) => PluginCloseStep::Blocked { reason: "recursive archive parent hydration retirement is blocked" },
                    Err(_) => PluginCloseStep::Blocked { reason: "recursive archive parent hydration could not retire" },
                };
            }
            if let Some(ingress) = self.rejected_ingress.as_mut() {
                return match ingress.close_step(maximum_items, maximum_bytes) {
                    Ok(PluginCloseStep::Complete) if ingress.terminal_is_empty() => {
                        self.rejected_ingress = None;
                        PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
                    }
                    Ok(step) => step,
                    Err(_) => PluginCloseStep::Blocked { reason: "recursive archive rejected member ingress could not retire" },
                };
            }
            if let Some(member) = self.member.as_mut() {
                let step = member.close_step(maximum_items, maximum_bytes);
                if step == PluginCloseStep::Complete && member.terminal_is_empty() {
                    self.member = None;
                    return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
                }
                return step;
            }
            if self.decoded_history.is_some() || self.history.is_some() {
                let history = self.decoded_history.take().or_else(|| self.history.as_mut().and_then(protocol::RetainedHistoryDecode::take_partial));
                let auxiliary = self.history.as_mut().map(protocol::RetainedHistoryDecode::take_auxiliary_owners);
                if let Some(decoder) = self.history.take() {
                    if !decoder.terminal_is_empty() {
                        self.history = Some(decoder);
                        return PluginCloseStep::Blocked { reason: "recursive archive history decoder retained an untransferred owner" };
                    }
                    drop(decoder);
                }
                self.retained = Some(semio_framework_value::retirement::owned_retirement((history, auxiliary)));
                return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
            }
            let Some(archive) = self.archive.as_mut() else { return PluginCloseStep::Complete };
            if let Some(member) = archive.members.last_mut() {
                let released_bytes = member.envelope_pack.len().min(maximum_bytes);
                if released_bytes != 0 {
                    member.envelope_pack.truncate(member.envelope_pack.len() - released_bytes);
                    return PluginCloseStep::Pending { released_items: 0, released_bytes };
                }
                if !member.envelope_pack.is_empty() {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                while self.close_identity_field < 10 && document_archive_member_identity_mut(member, self.close_identity_field).is_some_and(|field| field.is_empty()) {
                    self.close_identity_field += 1;
                }
                if let Some(field) = document_archive_member_identity_mut(member, self.close_identity_field) {
                    let bytes = field.chars().next_back().map_or(0, char::len_utf8);
                    if bytes > maximum_bytes {
                        return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    field.pop();
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: bytes };
                }
                drop(archive.members.pop());
                self.close_identity_field = 0;
                return PluginCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
            if !archive.parent_spr.is_empty() {
                let released_bytes = archive.parent_spr.len().min(maximum_bytes);
                if released_bytes == 0 {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                archive.parent_spr.truncate(archive.parent_spr.len() - released_bytes);
                return PluginCloseStep::Pending { released_items: 0, released_bytes };
            }
            if !archive.parent_pack.is_empty() {
                let released_bytes = archive.parent_pack.len().min(maximum_bytes);
                if released_bytes == 0 {
                    return PluginCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                archive.parent_pack.truncate(archive.parent_pack.len() - released_bytes);
                return PluginCloseStep::Pending { released_items: 0, released_bytes };
            }
            drop(self.archive.take());
            PluginCloseStep::Pending { released_items: 1, released_bytes: 0 }
        }
    }

    impl<P, Mutation> Drop for ActiveDocumentArchiveLoad<P, Mutation>
    where
        P: Clone + protocol::ToValue + protocol::FromValue,
        Mutation: Clone + protocol::ToValue + protocol::FromValue + store::Mutation<P>,
    {
        fn drop(&mut self) {
            assert!(
                std::thread::panicking()
                    || (self.archive.is_none()
                        && self.history.is_none()
                        && self.decoded_history.is_none()
                        && self.member.is_none()
                        && self.rejected_ingress.is_none()
                        && self.retained.is_none()
                        && self.hydration.is_none()
                        && self.replacement.is_none()),
                "recursive document archive operation reached Drop before its retained input owner was terminal empty",
            );
        }
    }

