        /// 📤️ ABI-level media delivery for ONE port — the route `AppCommand::MediaOut` reaches
        /// through `plugin_produce_media`.
        ///
        /// 🧭️ The `PluginApp` default this overrides ignores `port` entirely and answers the
        /// document pack for every port, so an app with a real exporter (`draw`'s `vector:out` →
        /// SVG, `writer`'s `text:out`, `lowpoly`'s `mesh:out`) shipped its own document pack under
        /// the exporting port's name — measured 2026-09-20 over a real compiled `draw` component:
        /// `MediaOut{port: "vector:out"}` answered 617 bytes of `drawing.drawing.pack v1`, with no
        /// `<svg` anywhere in it (`📓️wr3-headless-routes-view-state-export.md` §4.4). This body
        /// asks the app's own `export_media` first and keeps the pack for `artifact:out`, which is
        /// the port the provided `ArtifactEditor::export_media` body answers with exactly that.
        ///
        /// 🧭️ An app that declares no exporter for this port keeps the document-pack
        /// answer verbatim — the ONE behaviour this override preserves bit for bit.
        async fn produce_media(&mut self, port: &str) -> Result<MediaArtifact, MediaArtifactError> {
            if port == NATURAL_FILE_PORT {
                let codec = A::natural_file_codec().await.ok_or_else(|| MediaArtifactError::Payload("natural file exporter is not mounted".into()))?;
                self.refresh_cache().await.map_err(|fault| MediaArtifactError::Payload(fault.message))?;
                let snapshot = self.cache.as_ref().expect("cache refreshed above").1.as_ref();
                let data = A::encode_natural_file(snapshot).await.map_err(|error| MediaArtifactError::Payload(error.to_string()))?;
                return Ok(MediaArtifact {
                    descriptor: MediaArtifactDescriptor {
                        edge_id: None,
                        port_id: Some(port.to_string()),
                        kind_id: Some(codec.format_kind.to_string()),
                        media_type: None,
                        wire: MediaWireFormat::Binary { format_kind: codec.format_kind.to_string() },
                        blob_hash: None,
                    },
                    data,
                });
            }
            if port != "artifact:out" {
                match self.export_media(port).await {
                    Ok(Media { media_type, payload: MediaPayload::Structured { schema, json } }) => {
                        return Ok(MediaArtifact {
                            descriptor: MediaArtifactDescriptor { edge_id: None, port_id: Some(port.to_string()), kind_id: None, media_type: Some(media_type), wire: MediaWireFormat::Binary { format_kind: schema }, blob_hash: None },
                            data: json.into_bytes(),
                        })
                    }
                    Ok(Media { media_type, payload: MediaPayload::Intrinsic { schema, value } }) => {
                        let artifact = {
                            let mut accept = |_| true;
                            let mut control = semio_framework_value::NativeEncodeControl::new(ARTIFACT_SEGMENTED_DOWNLOAD_TOTAL_BYTES, &mut accept);
                            MediaArtifact::encode_intrinsic(port, media_type, &schema, &value, &mut control)
                        };
                        let mut close = semio_framework_value::retirement::owned_retirement(value);
                        while !close.terminal_is_empty() {
                            close.close_step(256, ARTIFACT_OUTPUT_CHUNK_BYTES).map_err(MediaArtifactError::Value)?;
                            semio_framework_async::yield_once().await;
                        }
                        return artifact;
                    }
                    Ok(Media { media_type, payload: MediaPayload::Binary { format_kind, blob_hash } }) => {
                        return Ok(MediaArtifact {
                            descriptor: MediaArtifactDescriptor { edge_id: None, port_id: Some(port.to_string()), kind_id: None, media_type: Some(media_type), wire: MediaWireFormat::Binary { format_kind }, blob_hash: Some(blob_hash) },
                            data: Vec::new(),
                        })
                    }
                    Err(MediaError::NotImplemented) => {}
                    Err(error) => return Err(MediaArtifactError::Payload(error.to_string())),
                }
            }
            let files = self.document_pack().await.map_err(|fault| MediaArtifactError::Payload(fault.message))?;
            Ok(MediaArtifact {
                descriptor: MediaArtifactDescriptor { edge_id: None, port_id: Some(port.to_string()), kind_id: None, media_type: None, wire: MediaWireFormat::Document { schema: self.artifact_schema().await.to_string() }, blob_hash: None },
                data: store::encode_document_pack_bytes(&files.pack, &files.spr).await,
            })
        }

        async fn consume_media(&mut self, port: &str, artifact: MediaArtifact) -> Result<(), MediaArtifactError> {
            if port != NATURAL_FILE_PORT {
                let schema_now = self.artifact_schema().await.to_string();
                return match artifact.descriptor.wire {
                    MediaWireFormat::Document { schema } if schema == schema_now => {
                        let (pack, spr) = store::decode_document_pack_bytes(&artifact.data).await.map_err(|error| MediaArtifactError::Payload(error.to_string()))?;
                        self.load_document_pack(&store::ArtifactPackFiles { pack, spr, ops: String::new() }).await.map_err(|fault| MediaArtifactError::Payload(fault.message))
                    }
                    MediaWireFormat::Document { schema } => Err(MediaArtifactError::SchemaMismatch { expected: schema_now, found: schema }),
                    MediaWireFormat::Binary { format_kind } => Err(MediaArtifactError::NoImporter(format_kind)),
                    MediaWireFormat::Intrinsic { .. } => {
                        let media = {
                            let mut accept = |_| true;
                            let mut control = semio_framework_value::NativeDecodeControl::new(ARTIFACT_SEGMENTED_DOWNLOAD_TOTAL_BYTES, &mut accept);
                            artifact.decode_intrinsic(&mut control)?
                        };
                        let instance_id = self.live_runtime_instance_id.ok_or_else(|| protocol::ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue, "intrinsic media import requires a bound live app instance"))?;
                        let actor = self.store.local_actor_id().unwrap_or("local").to_string();
                        self.dispatch_import_media(port, media, &ActionMeta { actor, instance_id, view_state: None }).await.map(|_| ()).map_err(MediaArtifactError::Import)
                    }
                };
            }
            let codec = A::natural_file_codec().await.ok_or_else(|| MediaArtifactError::NoImporter(port.to_string()))?;
            let MediaWireFormat::Binary { format_kind } = artifact.descriptor.wire else {
                return Err(MediaArtifactError::NoImporter(codec.format_kind.to_string()));
            };
            if format_kind != codec.format_kind {
                return Err(MediaArtifactError::NoImporter(format_kind));
            }
            let instance_id = self.live_runtime_instance_id.ok_or_else(|| MediaArtifactError::Payload("natural file import requires a bound live app instance".into()))?;
            let actor = self.store.local_actor_id().unwrap_or("local").to_string();
            let media_type = A::io().await.map_or(MediaType { class: MediaClass::Data, form: MediaForm::Value }, |io| io.artifact_media_type);
            let media = natural_file_input_media(codec, media_type, artifact.data);
            self.dispatch_import_media(port, media, &ActionMeta { actor, instance_id, view_state: None })
                .await
                .map(|_| ())
                .map_err(|fault| MediaArtifactError::Payload(fault.message))
        }

        /// 🎞️ Batch-only adapter. Registered interactive outputs are driven through the same
        /// externally addressable submission API; this loop is not used by UI/workflow entry points.
        async fn export_media(&mut self, port: &str) -> Result<Media, MediaError> {
            let tool_id = format!("export-media:{port}");
            if self.app_tool_registrations.contains_key(&tool_id) {
                let handle = self.submit_media_export(port).await?;
                loop {
                    match self.poll_media_export(&handle).await? {
                        ArtifactMediaExportPoll::Running { .. } => semio_framework_async::yield_once().await,
                        ArtifactMediaExportPoll::Complete(result) => return result.into_batch_media(),
                        ArtifactMediaExportPoll::Cancelled => return Err(MediaError::Payload(port.to_string(), "media export cancelled".into())),
                        ArtifactMediaExportPoll::Failed(detail) => return Err(MediaError::Payload(port.to_string(), detail)),
                    }
                }
            }
            self.refresh_cache().await.map_err(|error| MediaError::Payload(port.to_string(), error.message))?;
            let render_operation = self.live_render_operation();
            let parent_document_id = self.store.envelope().id.clone();
            let VcsArtifactApp { app: _, cache, child_content_root, transient_store, instance_operation_owner, .. } = self;
            let (_, snapshot, config, history) = cache.as_ref().expect("cache refreshed above");
            let doc = ArtifactView::with_render_context(snapshot.as_ref(), history.as_ref(), ChildContentView::clone(child_content_root), render_operation, parent_document_id, None).await;
            let _cfg = ConfigView { snapshot: config.as_ref(), window: None };
            let transient = transient_store.current_root();
            A::export_media_with_request_context(instance_operation_owner, port, &doc, &TransientView { snapshot: transient.as_ref(), window: None }).await
        }

        async fn submit_media_export(&mut self, port: &str) -> Result<ArtifactMediaExportHandle, MediaError> {
            let app_instance_id = self.live_runtime_instance_id.ok_or_else(|| MediaError::Payload(port.to_string(), "resumable media export requires a bound live app instance".into()))?;
            self.submit_owned_media_export(port, app_instance_id).await
        }

        async fn submit_media_export_checked(&mut self, port: &str, expected_parent_document_id: &str, expected_base_revision: u64) -> Result<ArtifactMediaExportHandle, MediaError> {
            let parent_document_id = self.store.envelope().id.as_str();
            let content_revision = self.store.content_revision();
            let base_revision = u64::from_be_bytes(content_revision[..8].try_into().expect("revision lane width"));
            if parent_document_id != expected_parent_document_id || base_revision != expected_base_revision {
                return Err(MediaError::Payload(port.to_string(), "media export resource authority is stale".into()));
            }
            let app_instance_id = self.live_runtime_instance_id.ok_or_else(|| MediaError::Payload(port.to_string(), "resumable media export requires a bound live app instance".into()))?;
            self.submit_owned_media_export(port, app_instance_id).await
        }

        async fn poll_media_export(&mut self, handle: &ArtifactMediaExportHandle) -> Result<ArtifactMediaExportPoll, MediaError> {
            self.poll_owned_media_export(handle).await
        }

        async fn cancel_media_export(&mut self, handle: &ArtifactMediaExportHandle) -> Result<(), MediaError> {
            self.cancel_owned_media_export(handle).await
        }

        async fn retain_media_export_result(&mut self, handle: &ArtifactMediaExportHandle, result: ArtifactMediaExportResult) -> Result<(), MediaError> {
            let operation_id = handle.operation_id.0;
            if !self.segmented_downloads.can_insert(operation_id) {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "media export download authority is saturated or already occupied".into()));
            }
            let active = self.media_closures.get_mut(operation_id).ok_or_else(|| MediaError::Payload(handle.parent_document_id.clone(), "completed media export lost its close authority".into()))?;
            if active.handle != *handle || !result.chunks.same_operation(&active.output_chunks) {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "completed media export authority mismatch".into()));
            }
            let output = ArtifactDownloadOutput::from_media_export(handle.clone(), result.mime_type, result.chunks).map_err(|error| MediaError::Payload(handle.parent_document_id.clone(), error.message))?;
            active.output_chunks = ArtifactOutputChunks::new(active.contract.max_output_bytes);
            self.segmented_downloads.insert_admitted(operation_id, output);
            Ok(())
        }

        async fn take_media_export_chunk(&mut self, handle: &ArtifactMediaExportHandle) -> Result<Option<Vec<u8>>, MediaError> {
            let operation_id = handle.operation_id.0;
            let output = self.segmented_downloads.get(operation_id).ok_or_else(|| MediaError::Payload(handle.parent_document_id.clone(), "unknown media export download handle".into()))?;
            if !output.owns_media_export(handle) {
                return Err(MediaError::Payload(handle.parent_document_id.clone(), "media export download handle authority mismatch".into()));
            }
            let chunk = output.chunks.take_chunk().map_err(|error| MediaError::Payload(handle.parent_document_id.clone(), error.message))?;
            if chunk.is_none() {
                let output = self.segmented_downloads.remove(operation_id).ok_or_else(|| MediaError::Payload(handle.parent_document_id.clone(), "terminal media export download changed before exact removal".into()))?;
                if !output.terminal_is_empty() {
                    self.segmented_downloads.insert_admitted(operation_id, output);
                    return Err(MediaError::Payload(handle.parent_document_id.clone(), "terminal media export download retained unread chunks".into()));
                }
                drop(output);
            }
            Ok(chunk)
        }

        async fn take_segmented_download_chunk(&mut self, operation_id: u64) -> Result<Option<Vec<u8>>, Fault> {
            let output = self.segmented_downloads.get(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.unknown-segmented-download"), format!("unknown segmented download operation {operation_id}")))?;
            let chunk = output.chunks.take_chunk()?;
            if chunk.is_none() {
                let output =
                    self.segmented_downloads.remove(operation_id).ok_or_else(|| Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-download-authority"), "terminal segmented download changed before exact removal"))?;
                if !output.terminal_is_empty() {
                    self.segmented_downloads.insert_admitted(operation_id, output);
                    return Err(Fault::new(FaultOrigin::Framework, FaultCode::new("interactive-job.segmented-download-terminal-not-empty"), "terminal segmented download retained unread chunks"));
                }
                drop(output);
            }
            Ok(chunk)
        }

        async fn import_media(&mut self, port: &str, media: Media, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let log_generation_before = self.log_generation;
            let result = self.dispatch_import_media(port, media, meta).await?;
            Ok(self.finish_recorded(log_generation_before, &format!("import-media:{port}"), result).await)
        }

        async fn media_fingerprint(&mut self, port: &str) -> Result<MediaFingerprint, MediaError> {
            self.refresh_cache().await.map_err(|error| MediaError::Payload(port.to_string(), error.message))?;
            let render_operation = self.live_render_operation();
            let parent_document_id = self.store.envelope().id.clone();
            let VcsArtifactApp { app: _, cache, child_content_root, .. } = self;
            let (_, snapshot, config, history) = cache.as_ref().expect("cache refreshed above");
            let doc = ArtifactView::with_render_context(snapshot.as_ref(), history.as_ref(), ChildContentView::clone(child_content_root), render_operation, parent_document_id, None).await;
            let _cfg = ConfigView { snapshot: config.as_ref(), window: None };
            A::media_fingerprint(port, &doc).await
        }
    }

    /// 🗃️ sdk-dedyn (O1/§1.5): generic over the per-plugin app enum `PA: PluginApp` — replaces
    /// `Box<dyn PluginApp>`.
    pub struct AppInstance<PA: PluginApp = NoPluginApp> {
        pub id: u32,
        pub app: PA,
        pub(crate) surface_contexts: crate::reactor::surface_context::SurfaceContexts,
    }
    //#endregion 🔖️DocumentContract

    /// 🔌️ A plugin-owned command executes at the program boundary, never through an arbitrary
    /// focused app. The manifest invocation carries its structural owner address; the handler may return
    /// the same host effects/events as app command dispatch without acquiring app document state.
    pub type PluginCommandHandler = Box<dyn Fn(&ManifestCommandInvocation, &ActionMeta) -> Result<InvocationResult, Fault> + Send>;

    /// 🗃️ sdk-dedyn (O1/§1.5): `Self::App: PluginApp` replaces `Box<dyn PluginApp>` — the single
    /// real impl (`Plugin<PA>` below) is never itself `dyn`-used (verified repo-wide), so this trait
    /// stays a plain AFIT contract, not a `#[dyn_enum]` family.
    pub trait PluginProgram: Send {
        type App: PluginApp;
        fn manifest(&self) -> PluginManifest;
        fn create_app(&self, app_id: &str) -> Option<Self::App>;
        fn handle_plugin_command(&self, invocation: &ManifestCommandInvocation, meta: &ActionMeta) -> Result<InvocationResult, Fault>;
    }

    pub struct Plugin<PA: PluginApp = NoPluginApp> {
        pub manifest: PluginManifest,
        descriptor_extras: crate::plugin_runtime::PluginDescriptorExtras,
        /// 📦️ Descriptor declarations for the example bodies this plugin registered as DEFERRED —
        /// collected at `register_app_factory`, where the leaf and its dialect are both in hand, and
        /// merged into the descriptor by `plugin_runtime::plugin_descriptor_extras`.
        deferred_example_assets: Vec<semio_framework::AssetDeclaration>,
        apps: HashMap<String, declarations::AppFactory<PA>>,
        command_handlers: HashMap<String, PluginCommandHandler>,
        runtime: PluginRuntimeRegistry,
    }

    impl<PA: PluginApp> Plugin<PA> {
        pub fn new(plugin_id: impl Into<String>, label: impl Into<String>, version: impl Into<String>) -> Self {
            Self {
                manifest: PluginManifest {
                    plugin_id: plugin_id.into(),
                    label: label.into(),
                    version: version.into(),
                    apps: Vec::new(),
                    examples: Vec::new(),
                    capabilities: Vec::new(),
                    topic_contributions: Vec::new(),
                    commands: Vec::new(),
                    artifact_kinds: Vec::new(),
                    hosted_artifact_kinds: Vec::new(),
                    dependencies: Vec::new(),
                    contributions: Vec::new(),
                },
                apps: HashMap::new(),
                command_handlers: HashMap::new(),
                runtime: PluginRuntimeRegistry::empty(),
                descriptor_extras: crate::plugin_runtime::PluginDescriptorExtras::default(),
                deferred_example_assets: Vec::new(),
            }
        }

        /// 🛂️ Keeps descriptor authority on the exact immutable plugin assembly.
        pub(crate) fn with_descriptor_extras(mut self, extras: crate::plugin_runtime::PluginDescriptorExtras) -> Self {
            self.descriptor_extras = extras;
            self
        }

        /// 🪪️ Reads descriptor fields belonging to this plugin, never the last assembled plugin.
        pub(crate) fn descriptor_extras(&self) -> &crate::plugin_runtime::PluginDescriptorExtras {
            &self.descriptor_extras
        }

        /// 📦️ Descriptor declarations for this plugin's DEFERRED example bodies — see the field.
        pub(crate) fn deferred_example_assets(&self) -> &[semio_framework::AssetDeclaration] {
            &self.deferred_example_assets
        }

        /// 🧬️ Installs the fully preflighted declaration authority before external rows commit.
        pub(crate) fn with_runtime_registry(mut self, runtime: PluginRuntimeRegistry) -> Self {
            self.runtime = runtime;
            self
        }

        /// 🧾️ Reads this plugin's immutable artifact-definition authority.
        pub fn artifact_definitions(&self) -> &ArtifactDefinitionRegistry {
            self.runtime.definitions()
        }

        /// 🧭️ Lists frozen host-media declarations in stable contribution-id order.
        pub fn host_media_handlers(&self) -> Vec<HostMediaHandlerDescriptor> {
            self.runtime.host_media_handlers.descriptors()
        }

        /// 🌊️ Lists frozen flow-extension descriptors in stable contribution-id order.
        pub fn flow_extensions(&self) -> Vec<FlowExtensionDescriptor> {
            self.runtime.flow_extensions.descriptors()
        }

        /// 📥️ Executes only the declared typed mesh bridge selected by the request.
        pub fn import_mesh(&self, request: &MeshImportRequest) -> Result<MeshImportResult, HostMediaRuntimeError> {
            self.runtime.host_media_handlers.mesh_import(request)
        }

        /// 📤️ Executes only the declared typed 2D SVG renderer selected by the request.
        pub fn export_two_d_svg(&self, request: &TwoDSvgExportRequest) -> Result<TwoDSvgExportResult, HostMediaRuntimeError> {
            self.runtime.host_media_handlers.two_d_svg_export(request)
        }

        pub(crate) fn wire_list_artifact_inference_services(&self) -> Vec<u8> {
            wire_list_artifact_inference_services_with_routes(self.runtime.inference_services(), self.runtime.routed_inferences())
        }

        pub(crate) fn wire_artifact_infer(&self, request: &[u8]) -> Result<Vec<u8>, ArtifactInferenceExecutionError> {
            wire_artifact_infer_from(self.runtime.inference_services(), request)
        }

        pub(crate) fn wire_list_artifact_mutations(&self) -> Vec<u8> {
            store::pack_rt::encode_wire_value(&semio_framework_value::ToValue::to_value(&self.runtime.mutation_roster_entries()))
        }

        pub(crate) fn wire_artifact_mutation_plan(&self, request: &[u8]) -> Result<Vec<u8>, Fault> {
            let request: WireArtifactMutationPlanRequest =
                store::pack_rt::decode_wire_value(request).map_err(|error| plugin_sdk_fault(error.to_string())).and_then(|value| semio_framework_value::FromValue::from_value(value).map_err(|error| plugin_sdk_fault(error.to_string())))?;
            if request.mutation_id.trim().is_empty() {
                return Err(plugin_sdk_fault("artifact-mutation-plan requires a non-empty mutation_id"));
            }
            let output = self.runtime.contributed_mutation_plan(&request.mutation_id, &request.artifact_kind, &request.snapshot_pack, &request.payload).map_err(|error| plugin_sdk_fault(error.to_string()))?;
            let result = WireArtifactMutationPlanResult {
                artifact_kind: request.artifact_kind,
                mutation_id: request.mutation_id,
                revision: request.revision,
                generation: request.generation,
                owner_ops: output.owner_ops,
                label: output.label,
                foreign: output.foreign,
            };
            Ok(store::pack_rt::encode_wire_value(&semio_framework_value::ToValue::to_value(&result)))
        }

        /// 🎛️ Declares a plugin-owned command and its program-level handler.
        pub fn plugin_command(mut self, command: CommandDefinition, handler: PluginCommandHandler) -> Self {
            assert!(!command.id.trim().is_empty(), "plugin {} command id must be non-empty", self.manifest.plugin_id);
            assert!(!self.command_handlers.contains_key(&command.id), "plugin {} duplicate command id {}", self.manifest.plugin_id, command.id);
            let mut arg_ids = HashSet::new();
            for arg in &command.args {
                assert!(!arg.id.trim().is_empty(), "plugin {} command {} has an empty arg id", self.manifest.plugin_id, command.id);
                assert!(arg_ids.insert(arg.id.clone()), "plugin {} command {} declares duplicate arg id {}", self.manifest.plugin_id, command.id, arg.id);
                if let semio_framework::ActionArgControl::Select { options } = &arg.control() {
                    assert!(!options.is_empty(), "plugin {} command {} arg {} is a Select with no options", self.manifest.plugin_id, command.id, arg.id);
                }
            }
            self.command_handlers.insert(command.id.clone(), handler);
            self.manifest.commands.push(command);
            self
        }

        /// 🔌️ Dispatches only commands structurally owned by this plugin.
        pub fn handle_plugin_command(&self, invocation: &ManifestCommandInvocation, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            let ManifestCommandOwnerAddress::Plugin { plugin_id } = &invocation.address.owner else {
                return Err(Fault::from("plugin command handler received a non-plugin owner"));
            };
            if plugin_id != &self.manifest.plugin_id {
                return Err(Fault::from(format!("plugin command owner {plugin_id} does not match {}", self.manifest.plugin_id)));
            }
            let handler = self.command_handlers.get(&invocation.address.command_id).ok_or_else(|| Fault::from(format!("unknown plugin command: {}", invocation.address.command_id)))?;
            let definition = self.manifest.commands.iter().find(|command| command.id == invocation.address.command_id).ok_or_else(|| Fault::from(format!("plugin command definition missing: {}", invocation.address.command_id)))?;
            let result = handler(invocation, meta)?;
            if matches!(definition.kind, ActionKind::View | ActionKind::Shell) && !result.mutations.is_empty() {
                return Err(Fault::from(format!("{:?}-kind plugin command '{}' must not emit mutations", definition.kind, definition.id)));
            }
            Ok(result)
        }

        pub fn capability(mut self, capability: CapabilityRequirement) -> Self {
            if !self.manifest.capabilities.contains(&capability) {
                self.manifest.capabilities.push(capability);
            }
            self
        }

        /// 🗂️ Declares one plugin-level artifact kind (library plugins use this; repeatable).
        pub fn artifact_kind(mut self, spec: ArtifactKindSpec) -> Self {
            self.manifest.artifact_kinds.push(spec);
            self
        }

        pub fn local_backbone_storage(self) -> Self {
            self.capability(CapabilityRequirement { artifact: ArtifactKind::Backbone, rights: Rights::Read, scope: Scope::Plugin }).capability(CapabilityRequirement { artifact: ArtifactKind::Backbone, rights: Rights::Write, scope: Scope::Plugin })
        }

        /// 🧬️ Registers an already-wrapped app factory (definition + bare fn pointer — see
        /// `crate::app::declarations::AppFactory`'s doc for why the definition travels with it)
        /// after typed assembly has completed.
        ///
        /// 📚️ An example is a document of the registering surface's DIALECT, shared by every app
        /// bound to it (editor and viewer alike) — never a property of this one app id.
        ///
        /// 📦️ A deferred body never becomes a manifest string, so its descriptor declaration
        /// has to be taken from the leaf HERE — `describe` only ever sees the (empty) row.
        pub fn register_app_factory(mut self, mut app: App, factory: declarations::AppFactory<PA>) -> Self {
            let mut factory = factory;
            join_framework_shared_action_dispositions(&mut app.definition);
            join_framework_shared_action_dispositions(&mut factory.definition);
            let dialect = app.definition.dialect.clone();
            let media_type = app.definition.io.artifact_media_type;
            self.manifest.apps.push(app.definition);
            for source in app.examples {
                if let Some(declaration) = source.deferred_body_asset(&dialect, media_type) {
                    if !self.deferred_example_assets.iter().any(|existing| existing.name == declaration.name) {
                        self.deferred_example_assets.push(declaration);
                    }
                }
                self.manifest.examples.push(source.into_example_definition(dialect.clone()));
            }
            self.apps.insert(self.manifest.apps.last().unwrap().id.clone(), factory);
            self
        }

        pub fn create_app(&self, app_id: &str) -> Option<PA> {
            self.apps.get(app_id).map(|factory| (factory.create)(&factory.definition))
        }

        /// 🪪️ The document schema the registered app opens — its type's own `DOCUMENT_SCHEMA`, recorded
        /// at registration, so nothing has to be constructed to learn it.
        pub fn app_document_schema(&self, app_id: &str) -> Option<&'static str> {
            self.apps.get(app_id).map(|factory| factory.document_schema)
        }

        /// 🧬️ The registered app's `codec` answers — functions of its type, recorded at registration, so a codec
        /// call constructs nothing.
        pub fn app_codec(&self, app_id: &str) -> Option<ArtifactCodecTableV1> {
            self.apps.get(app_id).map(|factory| factory.codec)
        }
    }

    impl<PA: PluginApp> PluginProgram for Plugin<PA> {
        type App = PA;

        fn manifest(&self) -> PluginManifest {
            self.manifest.clone()
        }

        fn create_app(&self, app_id: &str) -> Option<PA> {
            Plugin::create_app(self, app_id)
        }

        fn handle_plugin_command(&self, invocation: &ManifestCommandInvocation, meta: &ActionMeta) -> Result<InvocationResult, Fault> {
            Plugin::handle_plugin_command(self, invocation, meta)
        }
    }

    pub use super::builder::{NeedsLabel, NeedsVersion, PluginBuilder, Ready};

    //#region 🔖️WindowKits
    // 🪟️ The seven framework window kits (ticket 26/08/16/ARTIFACT-VIEWERS-AND-EDITORS-PER-SUBSET
    // §2.6) — each pairs a `WindowKindDefinition` (read-only + editable variants) with a `render`
    // function turning a plain owned view-model into a semantic `BuiltNode`. Frozen kind ids/labels/command ids,
    // not app-declared: apps compose these kits into their own `AppDefinition.window_kinds` rather
    // than each app hand-rolling a text/table/tree/image/mesh/document/media window from scratch.

    /// 🏗️ Shared `WindowKindDefinition` scaffold — every kit differs only in id/label/surface/icon/actions.
    fn window_kind_definition(id: &'static str, en: &'static str, de: &'static str, surface_kind: SurfaceKind, icon_id: &'static str, mut actions: Vec<ActionDefinition>) -> WindowKindDefinition {
        for action in &mut actions {
            action.semantics.execution.interactive_job = semio_framework::InteractiveJobClassification::Migrated;
        }
        WindowKindDefinition {
            id: id.into(),
            label: LocalizedLabel::native(en, de),
            body_key: id.into(),
            surface_kind: legacy_surface_kind(surface_kind),
            icon_id: icon_id.into(),
            options: WindowOptions::default(),
            actions,
            utilities: Vec::new(),
            interactions: Vec::new(),
            params_schema: None,
            artifact_snapshot_schema: None,
            input_event_schema: None,
            output_schema: None,
            capabilities: Vec::new(),
        }
    }

    /// 🪟️ A framework window kit: declares its read-only/editable `WindowKindDefinition` pair and
    /// renders its plain owned `ViewModel` into a semantic contract node. Product surfaces encode
    /// their typed scene payload through `semio_framework_ui_scene`; ordinary widgets use the
    /// contract builder DSL directly, so no renderer-owned `UiNode` crosses this SDK boundary.
    pub trait WindowKit {
        type ViewModel;
        const KIND_ID: &'static str;
        fn window_kind() -> WindowKindDefinition;
        fn editable_window_kind() -> WindowKindDefinition;
        fn render(view: &Self::ViewModel) -> UiAssemblyResult<BuiltNode>;
    }

    //#region 🔖️TextWindowKit
    /// 📝️ One language-tagged read-only text buffer (`TextEditorScene.settings_json` = `{"readOnly":true}`). An editable text
    /// window is never live whole-text typing: it is an explicit draft ([`TextEditView`], [`TextWindowKit::render_editable`]) —
