    pub const MEDIA_TRANSPORT_EXTENSION_ID: &str = "framework.media.transport@1";
    pub const MEDIA_PLAYBACK_OUTPUT_PORT: &str = "playback:out";

    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum MediaKind {
        Audio,
