//! 📄️ PDF 1.4 resolved pages in their declared reading order.
use semio_framework_value::{ValueError,ValueRefusalKind};
use super::{PdfSnapshot, PageDoc};
use store::sqlite_snapshot::{self, SqliteDatabase as Db, SqliteSnapshotControl as Control, SqliteSnapshotPhase as Phase, artifact::{Cell as C, Projection,FloatColumn,FloatRow,insert_ieee754}};

const PAGE_FLOATS:&[FloatColumn]=&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)];

impl store::ArtifactSqliteSnapshot for PdfSnapshot {
    fn encode_sqlite_snapshot_native(&self,encoding:sqlite_snapshot::SnapshotEncoding,control:&mut Control<'_>)->Result<store::io_schema::IoPayload,ValueError>{(||->Result<(),ValueError>{control.checkpoint(Phase::EncodeNative,0,0)?;control.check_rows(self.pages.len().checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"PDF page count overflow"))?)?;Ok(())})()?;store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|native|self.__dsl_to_record_controlled(native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),control)}
    fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,control:&mut Control<'_>)->Result<Self,ValueError>{store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record,native|Self::__dsl_from_record_controlled(record,native).map_err(|error|semio_framework_diagnostic::TextError::from_value_error(error,semio_framework_diagnostic::TextSpan::at(1,1))),control)}
    const SQLITE_SCHEMA: &'static str = include_str!("🗄️.sql");
    fn preflight_sqlite_snapshot_encoding(&self, _: sqlite_snapshot::SnapshotEncoding, control: &mut Control<'_>) -> Result<(),ValueError> {(||->Result<(),ValueError>{
        let mut bound = sqlite_snapshot::artifact::NativeEncodingBound::new(control)?;
        bound.add(4096)?;
        bound.repeated(self.schema.len(), 16)?;
        for page in &self.pages { bound.add(8192)?; bound.repeated(page.text.len(), 16)?; }
        bound.finish()
    })()}
    fn validate_sqlite_snapshot_subset(&self,dialect:&store::io_schema::ArtifactDialect,_database:&Db,control:&mut Control<'_>)->store::io_schema::IoResult<()>{(||->Result<store::io_schema::IoOutcome<()>,ValueError>{
        if dialect.artifact_kind!="s.stdio.pdf"||dialect.standard!="1.4"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"PDF1.4 snapshot does not own this dialect"));}
        control.checkpoint(Phase::ProjectSnapshot,0,1)?;
        let diagnostics=match dialect.subset.as_str(){"*"=>Vec::new(),"a"=>crate::standards::v1_4::subsets::a::schema::check_pdf_a_conformance(self),"x"=>crate::standards::v1_4::subsets::x::schema::check_pdf_x_conformance(self),_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"PDF1.4 subset has no semantic validator"))};
        control.checkpoint(Phase::ProjectSnapshot,1,1)?;
        Ok(store::io_schema::IoOutcome{value:(),diagnostics})
    })().map_err(store::io_schema::IoError::from_value_error)}
    fn to_sqlite_database(&self, control: &mut Control<'_>) -> Result<Db,ValueError> {(||->Result<Db,ValueError>{
        let mut projection=Projection::new(Self::SQLITE_SCHEMA,control)?;
        projection.check_rows(self.pages.len().checked_add(1).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"PDF page count overflow"))?)?;
        projection.insert("pdf14_document",&[C::Text(&self.schema)])?;
        for(ordinal,page)in self.pages.iter().enumerate(){insert_ieee754(&mut projection,"pdf14_page",&[C::Integer(1),C::Integer(ordinal as i64),C::Real(page.width),C::Real(page.height),C::Text(&page.text)],PAGE_FLOATS)?;}
        projection.finish()
    })()}
    fn from_sqlite_database(db:&Db,control:&mut Control<'_>)->Result<Self,ValueError>{(||->Result<Self,ValueError>{
        control.checkpoint(Phase::ReconstructSnapshot,0,0)?;
        sqlite_snapshot::validate_sqlite_database_schema(db,Self::SQLITE_SCHEMA,control.limits())?;
        control.check_database(db,Phase::ReconstructSnapshot)?;
        let document=db.table("pdf14_document")?.single_row()?;
        if document.rowid!=1||document.values.len()!=2||document.integer(0)?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid PDF document identity"));}
        let rows=&db.table("pdf14_page")?.rows;
        let mut sorted=Vec::with_capacity(rows.len());let mut identities=std::collections::BTreeSet::new();
        for(index,row)in rows.iter().enumerate(){if index%256==0{control.checkpoint(Phase::ReconstructSnapshot,index,rows.len())?;}if row.values.len()!=10||row.rowid<=0||row.integer(0)?!=row.rowid||!identities.insert(row.rowid)||row.integer(1)?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid PDF page identity or document relationship"));}sorted.push((row.integer(2)?,FloatRow::new(row,PAGE_FLOATS)?));}
