        if let Some(error)=cancelled{return Err(error);}
        let mut pages=Vec::with_capacity(rows.len());
        for(index,(ordinal,row))in sorted.into_iter().enumerate(){if ordinal!=index as i64{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"PDF page order must be contiguous and unique"));}if index%256==0{control.checkpoint(Phase::ReconstructSnapshot,index,rows.len())?;}pages.push(PageDoc{width:row.real(3)?,height:row.real(4)?,text:sqlite_snapshot::artifact::Reconstruction::new(control)?.text(row.text(5)?)?});}
        control.checkpoint(Phase::ReconstructSnapshot,rows.len(),rows.len())?;
        Ok(Self{schema:sqlite_snapshot::artifact::Reconstruction::new(control)?.text(document.text(1)?)?,pages})
    })()}
}

