        None
    }

    fn terminal_drop_is_shallow(&self) -> bool {
        true
    }
}

fn never_progresses_fixture(_job: u64, _input: &[u8], _restored: Option<&[u8]>) -> Result<Box<dyn BoundedJob>, Vec<u8>> {
    Ok(Box::new(NeverProgressesFixture))
