/// 🧱️ Projects only the explicitly shared native DocBlock tree with an iterative ownership walk.
pub fn project_block_collection(blocks:&[DocBlock],t:DocSqliteTables,styles:Option<&BTreeMap<&str,i64>>,images:Option<&BTreeMap<&str,i64>>,p:&mut Projection<'_,'_>)->Result<i64,ValueError>{
let root=p.insert_float(t.collection,&[])?;let mut pending=vec![(root,blocks)];while let Some((collection,blocks))=pending.pop(){p.check_rows(blocks.len().checked_add(pending.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"document traversal count overflow"))?)?;for(ordinal,block)in blocks.iter().enumerate(){let kind=match block{DocBlock::Paragraph{..}=>"paragraph",DocBlock::Heading{..}=>"heading",DocBlock::List{..}=>"list",DocBlock::Table{..}=>"table",DocBlock::Code{..}=>"code",DocBlock::Quote{..}=>"quote",DocBlock::Image{..}=>"image",DocBlock::PageBreak=>"pageBreak"};let id=p.insert_float(t.block,&[Cell::Text(kind)])?;p.insert_float(t.member,&[Cell::Integer(collection),Cell::Integer(number(ordinal)?),Cell::Integer(id)])?;
