DocBlock::Heading{level,style_id,..}=>p.insert_key_float(t.heading,id,&[Cell::Integer(i64::from(*level)),reference(style_id.as_deref(),styles)?])?,
DocBlock::List{ordered,items}=>{p.insert_key_float(t.list,id,&[Cell::Integer(i64::from(*ordered))])?;p.check_rows(pending.len().checked_add(items.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"document list traversal overflow"))?)?;for(ordinal,item)in items.iter().enumerate(){let child=p.insert_float(t.collection,&[])?;p.insert_float(t.list_item,&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(child)])?;pending.push((child,item.blocks.as_slice()));}},
DocBlock::Table{rows}=>{p.insert_key_float(t.table,id,&[])?;for(ordinal,row)in rows.iter().enumerate(){let row_id=p.insert_float(t.table_row,&[Cell::Integer(id),Cell::Integer(number(ordinal)?)])?;p.check_rows(pending.len().checked_add(row.cells.len()).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"document table traversal overflow"))?)?;for(ordinal,cell)in row.cells.iter().enumerate(){let child=p.insert_float(t.collection,&[])?;p.insert_float(t.table_cell,&[Cell::Integer(row_id),Cell::Integer(number(ordinal)?),Cell::Integer(child)])?;pending.push((child,cell.blocks.as_slice()));}}},
