        match alteration {
            0 => { broken.table_mut("stl_vertex").unwrap().rows.pop(); },
            1 => broken.table_mut("stl_vertex").unwrap().rows[0].values[1] = SqliteValue::Integer(999),
            _ => broken.table_mut("stl_facet").unwrap().rows[1].values[2] = SqliteValue::Integer(0),
