    let fixture: serde_json::Value = serde_json::from_str(include_str!("../../🧫️fixtures/🫳️ownership/🔣️.json")).unwrap();
    let text = fixture["unit"].as_str().unwrap().repeat(fixture["repeats"].as_u64().unwrap() as usize);
