    fn sift<T>(values: &mut [T], mut root: usize, end: usize, work: &mut usize, control: &mut SqliteSnapshotControl<'_>, compare: &mut impl FnMut(&T, &T) -> Result<std::cmp::Ordering>) -> Result<()> {
