                "dxf_entity" => { if row.integer(1)? != 1 { return Err(ValueError::new(ValueRefusalKind::InvalidValue,"DXF entity document reference must be one")); } Some((name,optional_integer(row,2)?,3)) },
                _ => Some((name,Some(row.integer(1)?),2)),
            };
