/// 🧮️ Projects owned semantic rows under the caller's typed resource control.
pub fn project_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{
let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key_float("semio_mesh_document",1,&[Cell::Text(&self.schema)])?;let mut textures=BTreeMap::new();for(ordinal,texture)in self.textures.iter().enumerate(){if textures.contains_key(texture.id.as_str()){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio mesh texture identifier"));}let id=p.insert_float("semio_mesh_texture",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&texture.id),Cell::Text(&texture.mime),Cell::Blob(&texture.bytes) ])?;textures.insert(texture.id.as_str(),id);}let mut materials=BTreeMap::new();for(ordinal,material)in self.materials.iter().enumerate(){let c=material.base_color;let id=p.insert_float("semio_mesh_material",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&material.id),Cell::Float32(c.r),Cell::Float32(c.g),Cell::Float32(c.b),Cell::Float32(c.a),Cell::Float32(material.metallic),Cell::Float32(material.roughness),texture_reference(&textures,material.base_color_texture.as_deref())?,texture_reference(&textures,material.metallic_roughness_texture.as_deref())?,texture_reference(&textures,material.normal_texture.as_deref())?,texture_reference(&textures,material.occlusion_texture.as_deref())?,texture_reference(&textures,material.emissive_texture.as_deref())?])?;if materials.insert(material.id.as_str(),id).is_some(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio mesh material identifier"));}}
let mut meshes=BTreeSet::new();for(ordinal,mesh)in self.meshes.iter().enumerate(){let mesh_id=p.insert_float("semio_mesh_mesh",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&mesh.id)])?;if !meshes.insert(mesh.id.as_str()){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio mesh identifier"));}let mut primitive_ids=BTreeSet::new();for(ordinal,primitive)in mesh.primitives.iter().enumerate(){if !primitive_ids.insert(primitive.id.as_str()){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"duplicate Semio mesh primitive identifier"));}let material=match &primitive.material_id{None=>Cell::Null,Some(id)=>Cell::Integer(*materials.get(id.as_str()).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"dangling Semio mesh primitive material"))?)};let id=p.insert_float("semio_mesh_primitive",&[Cell::Integer(mesh_id),Cell::Integer(number(ordinal)?),Cell::Text(&primitive.id),Cell::Text(topology(primitive.topology)),material])?;let mut first_position=0;
for(ordinal,position)in primitive.positions.iter().enumerate(){let row=p.insert_float("semio_mesh_position",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(position.x),Cell::Real(position.y),Cell::Real(position.z)])?;if ordinal==0{first_position=row;}}
for(ordinal,normal)in primitive.normals.iter().enumerate(){p.insert_float("semio_mesh_normal",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(normal.x),Cell::Real(normal.y),Cell::Real(normal.z)])?;}
for(ordinal,uv)in primitive.uvs.iter().enumerate(){p.insert_float("semio_mesh_uv",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(uv.u),Cell::Real(uv.v)])?;}
for(ordinal,color)in primitive.colors.iter().enumerate(){p.insert_float("semio_mesh_color",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Float32(color.r),Cell::Float32(color.g),Cell::Float32(color.b),Cell::Float32(color.a)])?;}
for(ordinal,index)in primitive.indices.iter().enumerate(){if usize::try_from(*index).map_err(|error|ValueError::new(ValueRefusalKind::InvalidValue,error.to_string()))?>=primitive.positions.len(){return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Semio mesh vertex index is out of bounds"));}p.insert_float("semio_mesh_index",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Integer(i64::from(*index)),Cell::Integer(first_position.checked_add(i64::from(*index)).ok_or_else(||ValueError::new(ValueRefusalKind::WorkLimit,"Semio mesh position identifier overflow"))?)])?;}}}
p.finish()
}
}

