        let mut accept=|_|true;let output=snapshot.to_value_controlled(&mut NativeEncodeControl::new(maximum,&mut accept)).unwrap();let pack::value::DslValue::Object(fields)=&output else{panic!("PDF output must preserve its declared fields")};assert_eq!(fields.len(),plan["fieldCount"].as_u64().unwrap()as usize);assert_eq!(output,snapshot.to_value());assert_eq!(PdfSnapshot::from_value(output).unwrap(),snapshot);
        let mut interior=false;let mut cancel=|event:NativeEncodeProgress|if event.total==snapshot.schema.len()&&event.completed>=plan["cancelAt"].as_u64().unwrap()as usize&&event.completed<event.total{interior=true;false}else{true};assert!(snapshot.to_value_controlled(&mut NativeEncodeControl::new(maximum,&mut cancel)).is_err());assert!(interior);let mut accept=|_|true;let mut control=NativeEncodeControl::new(1,&mut accept);assert!(snapshot.to_value_controlled(&mut control).is_err());assert_eq!(control.owned_bytes(),0);
        use std::{io::Write,process::{Command,Stdio}};let script="import Ajv from'ajv';import{Database}from'bun:sqlite';const x=JSON.parse(await Bun.stdin.text());if(!new Ajv({strict:true}).validate(x.schema,x.plan))throw Error('fixture');const d=new Database(':memory:');d.run('CREATE TABLE literal(id INTEGER PRIMARY KEY,text TEXT NOT NULL,left_id BLOB NOT NULL,right_id BLOB NOT NULL)');d.run('INSERT INTO literal VALUES(1,?,?,?)',x.plan.text.repeat(x.plan.repeatCount),Uint8Array.from(x.plan.documentId.left),Uint8Array.from(x.plan.documentId.right));const row=d.query('SELECT text,hex(left_id) AS left_id,hex(right_id) AS right_id FROM literal').get();await Bun.write(Bun.stdout,JSON.stringify(row));d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(serde_json::json!({"plan":plan,"schema":schema}).to_string().as_bytes()).unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));let oracle:serde_json::Value=serde_json::from_slice(&result.stdout).unwrap();assert_eq!(oracle["text"].as_str().unwrap(),snapshot.schema);assert_eq!(oracle["left_id"],"0001FF");assert_eq!(oracle["right_id"],"");
