    let mut snapshot = fixture();
    use semio_s_artifact_stdio_xml::schema::snapshot::{XmlAttr, XmlNode};
    let values = [("x", i64::MIN), ("y", i64::MAX), ("cx", 9007199254740993), ("cy", -9007199254740993)];
