            for _ in 0..plan["depth"].as_u64().unwrap() {
                node = semio_s_artifact_stdio_xml::schema::snapshot::XmlNode::Element { name: "node".into(), attrs: vec![], children: vec![node] };
            }
            snapshot.xml_parts[0].document.root = Some(node);
