        PathSegment::LineTo { to: SemioPoint2 { x: width, y: 0.0 } },
        PathSegment::LineTo { to: SemioPoint2 { x: width, y: height } },
        PathSegment::LineTo { to: SemioPoint2 { x: 0.0, y: height } },
