    use std::sync::OnceLock;

    /// 🗣️ The five hand-authored `dsl::LanguageSpec`s this subset already carried before this
    /// ticket (the old artifact root's `pilot_languages()`) — `OnceLock` because `dsl::passthrough_hooks`
